// Daily mantra cards, part 1: well-known ṛks of the Ṛgveda.
// { at, m: [meaning en, kn], w: [[word, en, kn] …], u: [use and significance en, kn] }
export const CARDS = [
  { at: 'rv 3.62.10',
    m: ['We meditate on that most excellent radiance of the god Savitṛ; may he impel our minds.', 'ಸವಿತೃ ದೇವನ ಆ ಶ್ರೇಷ್ಠ ತೇಜಸ್ಸನ್ನು ಧ್ಯಾನಿಸುತ್ತೇವೆ; ಅವನು ನಮ್ಮ ಬುದ್ಧಿಗಳನ್ನು ಪ್ರೇರೇಪಿಸಲಿ.'],
    w: [['वरेण्यम्', '“to be chosen”, hence most excellent — a gerundive of √vṛ, to choose.', '"ಆರಿಸಬೇಕಾದದ್ದು", ಆದ್ದರಿಂದ ಶ್ರೇಷ್ಠ — √ವೃ (ಆರಿಸು) ಧಾತುವಿನ ಕೃತ್ಯಪ್ರತ್ಯಯ ರೂಪ.'],
      ['धीमहि', '“may we meditate, may we hold (in mind)” — 1st person plural, optative, middle.', '"ಧ್ಯಾನಿಸೋಣ, ಮನಸ್ಸಿನಲ್ಲಿ ಧರಿಸೋಣ" — ಉತ್ತಮಪುರುಷ ಬಹುವಚನ, ವಿಧಿಲಿಙ್, ಆತ್ಮನೇಪದ.'],
      ['प्रचोदयात्', '“may he impel” — from pra + √cud, to urge on; the prayer is for the mind itself to be moved.', '"ಪ್ರೇರೇಪಿಸಲಿ" — ಪ್ರ + √ಚುದ್ (ಪ್ರೇರಿಸು); ಬುದ್ಧಿಯೇ ಚಲಿಸಲಿ ಎಂಬ ಪ್ರಾರ್ಥನೆ.']],
    u: ['The Gāyatrī or Sāvitrī mantra. It is given at upanayana and repeated in sandhyāvandana at dawn, noon and dusk, prefixed with Om and the three vyāhṛtis (bhūr bhuvaḥ svaḥ). Manu calls it the mother of the Vedas.', 'ಗಾಯತ್ರೀ ಅಥವಾ ಸಾವಿತ್ರೀ ಮಂತ್ರ. ಉಪನಯನದಲ್ಲಿ ಉಪದೇಶಿಸಲಾಗುತ್ತದೆ; ಪ್ರಾತಃ, ಮಧ್ಯಾಹ್ನ, ಸಾಯಂ ಸಂಧ್ಯಾವಂದನೆಯಲ್ಲಿ ಓಂ ಮತ್ತು ಭೂರ್ಭುವಃಸ್ವಃ ಎಂಬ ವ್ಯಾಹೃತಿಗಳೊಂದಿಗೆ ಜಪ. ಮನು ಇದನ್ನು ವೇದಮಾತೆ ಎನ್ನುತ್ತಾನೆ.'] },
  { at: 'rv 7.59.12',
    m: ['We worship the three-eyed one, fragrant, who increases nourishment. As a ripe cucumber from its stalk, may I be freed from death, not from immortality.', 'ಸುಗಂಧಿಯೂ ಪುಷ್ಟಿವರ್ಧನನೂ ಆದ ತ್ರ್ಯಂಬಕನನ್ನು ಪೂಜಿಸುತ್ತೇವೆ. ಕಳಿತ ಸೌತೆಕಾಯಿ ತೊಟ್ಟಿನಿಂದ ಬಿಡುವಂತೆ ಮೃತ್ಯುವಿನಿಂದ ಬಿಡುಗಡೆಯಾಗಲಿ, ಅಮೃತದಿಂದಲ್ಲ.'],
    w: [['त्र्यम्बकम्', '“three-eyed” or “having three mothers” — tri + ambaka; a name of Rudra.', '"ಮೂರು ಕಣ್ಣುಳ್ಳವನು" ಅಥವಾ "ಮೂವರು ತಾಯಂದಿರುಳ್ಳವನು" — ತ್ರಿ + ಅಂಬಕ; ರುದ್ರನ ಹೆಸರು.'],
      ['उर्वारुकम्', 'a cucumber or melon: when ripe it leaves the vine of itself, without force.', 'ಸೌತೆಕಾಯಿ ಅಥವಾ ಕರ್ಬೂಜ: ಹಣ್ಣಾದಾಗ ಬಲವಿಲ್ಲದೆ ತಾನಾಗಿ ಬಳ್ಳಿಯನ್ನು ಬಿಡುತ್ತದೆ.'],
      ['मुक्षीय', '“may I be released” — aorist optative (precative), middle, of √muc.', '"ಬಿಡುಗಡೆಯಾಗಲಿ" — √ಮುಚ್ ಧಾತುವಿನ ಆಶೀರ್ಲಿಙ್, ಆತ್ಮನೇಪದ.']],
    u: ['The Mahāmṛtyuñjaya mantra, repeated for health, long life and a peaceful death, and used in homas for recovery. The image of the ripe fruit asks for a release that comes naturally, in its time.', 'ಮಹಾಮೃತ್ಯುಂಜಯ ಮಂತ್ರ: ಆರೋಗ್ಯ, ದೀರ್ಘಾಯುಸ್ಸು, ಶಾಂತ ಮರಣಕ್ಕಾಗಿ ಜಪ; ರೋಗನಿವಾರಣೆಯ ಹೋಮಗಳಲ್ಲಿ ಬಳಕೆ. ಕಳಿತ ಹಣ್ಣಿನ ಉಪಮೆ ಸಹಜವಾಗಿ, ಕಾಲಕ್ಕೆ ಸರಿಯಾಗಿ ಬರುವ ಮುಕ್ತಿಯನ್ನು ಕೇಳುತ್ತದೆ.'] },
  { at: 'rv 1.1.1',
    m: ['I praise Agni, the one placed in front, god of the sacrifice, the priest who invokes, the best giver of treasures.', 'ಮುಂದೆ ಇರಿಸಲ್ಪಟ್ಟವನೂ ಯಜ್ಞದ ದೇವನೂ ಋತ್ವಿಜನೂ ಹೋತೃವೂ ರತ್ನಗಳನ್ನು ಅತ್ಯಧಿಕವಾಗಿ ನೀಡುವವನೂ ಆದ ಅಗ್ನಿಯನ್ನು ಸ್ತುತಿಸುತ್ತೇನೆ.'],
    w: [['ईळे', '“I praise” — 1st person singular, present, middle, of √īḍ.', '"ಸ್ತುತಿಸುತ್ತೇನೆ" — √ಈಡ್ ಧಾತು, ಉತ್ತಮಪುರುಷ ಏಕವಚನ, ವರ್ತಮಾನ, ಆತ್ಮನೇಪದ.'],
      ['पुरोहितम्', '“placed in front” — puras + hita; the family priest who stands before the people, as fire stands before the altar.', '"ಮುಂದೆ ಇರಿಸಲ್ಪಟ್ಟವನು" — ಪುರಸ್ + ಹಿತ; ಜನರ ಮುಂದೆ ನಿಲ್ಲುವ ಪುರೋಹಿತ, ವೇದಿಯ ಮುಂದಿನ ಅಗ್ನಿಯಂತೆ.'],
      ['रत्नधातमम्', '“best bestower of treasures” — ratna + dhā + the superlative -tama.', '"ರತ್ನಗಳನ್ನು ಅತಿಶಯವಾಗಿ ನೀಡುವವನು" — ರತ್ನ + ಧಾ + ತಮಪ್ (ಅತಿಶಯ).']],
    u: ['The first ṛk of the Ṛgveda. Daily svādhyāya and the brahmayajña begin with it, and every recitation of the Saṃhitā starts here. Fire, the meeting point of humans and gods, opens the Veda.', 'ಋಗ್ವೇದದ ಮೊದಲ ಋಕ್. ನಿತ್ಯ ಸ್ವಾಧ್ಯಾಯ ಮತ್ತು ಬ್ರಹ್ಮಯಜ್ಞ ಇದರಿಂದಲೇ ಆರಂಭ; ಸಂಹಿತೆಯ ಪ್ರತಿ ಪಾರಾಯಣ ಇಲ್ಲಿಂದ. ಮನುಷ್ಯರು ಮತ್ತು ದೇವತೆಗಳು ಸೇರುವ ಅಗ್ನಿಯಿಂದಲೇ ವೇದ ತೆರೆಯುತ್ತದೆ.'] },
  { at: 'rv 1.89.1',
    m: ['Let auspicious intentions come to us from every side, unhindered, unobstructed, victorious, so that the gods may always be with us for our growth, our unfailing guardians day after day.', 'ಮಂಗಳಕರ ಸಂಕಲ್ಪಗಳು ಎಲ್ಲ ದಿಕ್ಕುಗಳಿಂದ ಅಡೆತಡೆಯಿಲ್ಲದೆ, ಜಯಶೀಲವಾಗಿ ನಮ್ಮೆಡೆಗೆ ಬರಲಿ; ದೇವತೆಗಳು ಸದಾ ನಮ್ಮ ವೃದ್ಧಿಗಾಗಿ, ಪ್ರತಿದಿನ ನಮ್ಮನ್ನು ಕಾಯುವವರಾಗಿ ಇರಲಿ.'],
    w: [['भद्राः', '“auspicious, good” — the key word of the whole hymn, often called the Bhadra Sūkta.', '"ಮಂಗಳಕರ, ಶುಭ" — ಇಡೀ ಸೂಕ್ತದ ಮುಖ್ಯ ಪದ; ಇದನ್ನು ಭದ್ರಸೂಕ್ತ ಎನ್ನುತ್ತಾರೆ.'],
      ['क्रतवः', '“powers of will, intentions, resolves” — plural of kratu.', '"ಸಂಕಲ್ಪಶಕ್ತಿಗಳು, ಉದ್ದೇಶಗಳು" — ಕ್ರತು ಪದದ ಬಹುವಚನ.'],
      ['विश्वतः', '“from all sides” — viśva + the ablative suffix -tas.', '"ಎಲ್ಲ ಕಡೆಗಳಿಂದ" — ವಿಶ್ವ + ತಸಿಲ್ ಪ್ರತ್ಯಯ.']],
    u: ['“Ā no bhadrāḥ kratavo yantu viśvataḥ” is recited at the start of study, of a new undertaking, and in many śānti prayers. It asks for good thoughts from anywhere at all — openness as a blessing.', '"ಆ ನೋ ಭದ್ರಾಃ ಕ್ರತವೋ ಯಂತು ವಿಶ್ವತಃ" — ಅಧ್ಯಯನದ ಆರಂಭದಲ್ಲಿ, ಹೊಸ ಕಾರ್ಯದ ಆರಂಭದಲ್ಲಿ, ಅನೇಕ ಶಾಂತಿಪ್ರಾರ್ಥನೆಗಳಲ್ಲಿ ಪಠಣ. ಎಲ್ಲಿಂದಾದರೂ ಒಳ್ಳೆಯ ಚಿಂತನೆಗಳು ಬರಲಿ — ತೆರೆದ ಮನಸ್ಸೇ ಆಶೀರ್ವಾದ.'] },
  { at: 'rv 1.164.46',
    m: ['They call him Indra, Mitra, Varuṇa, Agni, and he is the heavenly well-winged Garutmān. What is One, the wise speak of in many ways: they call it Agni, Yama, Mātariśvan.', 'ಅವನನ್ನು ಇಂದ್ರ, ಮಿತ್ರ, ವರುಣ, ಅಗ್ನಿ ಎನ್ನುತ್ತಾರೆ; ಅವನೇ ದಿವ್ಯ ಸುಪರ್ಣ ಗರುತ್ಮಾನ್. ಸತ್ಯ ಒಂದೇ; ಜ್ಞಾನಿಗಳು ಅದನ್ನು ಅನೇಕ ಬಗೆಯಲ್ಲಿ ಹೇಳುತ್ತಾರೆ — ಅಗ್ನಿ, ಯಮ, ಮಾತರಿಶ್ವಾ ಎಂದು.'],
    w: [['एकं सत्', '“one being, one reality” — sat is the present participle of √as, to be.', '"ಒಂದೇ ಇರುವಿಕೆ, ಒಂದೇ ಸತ್ಯ" — ಸತ್ ಎಂಬುದು √ಅಸ್ (ಇರು) ಧಾತುವಿನ ವರ್ತಮಾನ ಕೃದಂತ.'],
      ['विप्राः', '“the inspired ones, sages” — from √vip, to tremble (with inspiration).', '"ಪ್ರೇರಿತರು, ಜ್ಞಾನಿಗಳು" — √ವಿಪ್ (ಕಂಪಿಸು, ಸ್ಫೂರ್ತಿಯಿಂದ) ಧಾತುವಿನಿಂದ.'],
      ['बहुधा', '“in many ways” — bahu + the adverbial suffix -dhā.', '"ಅನೇಕ ಬಗೆಯಲ್ಲಿ" — ಬಹು + ಧಾ ಪ್ರತ್ಯಯ.']],
    u: ['From Dīrghatamas’s riddle hymn (Asya Vāmasya). “Ekaṃ sad viprā bahudhā vadanti” is among the most quoted lines of the Veda: the many gods are names of one reality — the root of Indian tolerance of many paths.', 'ದೀರ್ಘತಮರ "ಅಸ್ಯ ವಾಮಸ್ಯ" ಒಗಟಿನ ಸೂಕ್ತದಿಂದ. "ಏಕಂ ಸದ್ ವಿಪ್ರಾ ಬಹುಧಾ ವದಂತಿ" ವೇದದ ಅತ್ಯಂತ ಉಲ್ಲೇಖಿತ ಸಾಲುಗಳಲ್ಲೊಂದು: ಅನೇಕ ದೇವತೆಗಳು ಒಂದೇ ಸತ್ಯದ ಹೆಸರುಗಳು — ಅನೇಕ ಮಾರ್ಗಗಳ ಸಹಿಷ್ಣುತೆಯ ಮೂಲ.'] },
  { at: 'rv 1.164.20',
    m: ['Two birds, yoked companions, cling to the same tree. One of them eats the sweet fig; the other, not eating, looks on.', 'ಜೊತೆಗಾರರಾದ ಸ್ನೇಹಿತರಾದ ಎರಡು ಹಕ್ಕಿಗಳು ಒಂದೇ ಮರವನ್ನು ಆಶ್ರಯಿಸಿವೆ. ಒಂದು ಸಿಹಿ ಹಣ್ಣನ್ನು ತಿನ್ನುತ್ತದೆ; ಇನ್ನೊಂದು ತಿನ್ನದೆ ನೋಡುತ್ತಿರುತ್ತದೆ.'],
    w: [['सयुजा सखाया', '“yoked together, two friends” — Vedic dual forms in -ā (classical sayujau sakhāyau).', '"ಜೊತೆಯಾದ ಇಬ್ಬರು ಸ್ನೇಹಿತರು" — ವೈದಿಕ ದ್ವಿವಚನ -ಆ ರೂಪ (ಲೌಕಿಕದಲ್ಲಿ ಸಯುಜೌ ಸಖಾಯೌ).'],
      ['पिप्पलम्', 'a fig or sweet berry — the fruit of experience.', 'ಅಶ್ವತ್ಥದ ಹಣ್ಣು ಅಥವಾ ಸಿಹಿ ಹಣ್ಣು — ಅನುಭವದ ಫಲ.'],
      ['अभि चाकशीति', '“keeps looking on” — intensive of √kāś, to shine, see.', '"ನೋಡುತ್ತಲೇ ಇರುತ್ತದೆ" — √ಕಾಶ್ (ಹೊಳೆ, ನೋಡು) ಧಾತುವಿನ ಯಙ್ಲುಗಂತ (ತೀವ್ರಾರ್ಥ) ರೂಪ.']],
    u: ['Quoted word for word in the Muṇḍaka (3.1.1) and Śvetāśvatara (4.6) Upaniṣads: the two birds are the individual self, who tastes the fruits of action, and the Self, the silent witness.', 'ಮುಂಡಕ (೩.೧.೧) ಮತ್ತು ಶ್ವೇತಾಶ್ವತರ (೪.೬) ಉಪನಿಷತ್ತುಗಳಲ್ಲಿ ಯಥಾವತ್ ಉಲ್ಲೇಖ: ಎರಡು ಹಕ್ಕಿಗಳು ಕರ್ಮಫಲವನ್ನು ಸವಿಯುವ ಜೀವಾತ್ಮ ಮತ್ತು ಮೌನ ಸಾಕ್ಷಿಯಾದ ಪರಮಾತ್ಮ.'] },
  { at: 'rv 10.129.1',
    m: ['Then there was neither non-being nor being; there was no air, nor sky beyond. What covered all? Where? In whose keeping? Was there water, deep beyond measure?', 'ಆಗ ಅಸತ್ತೂ ಇರಲಿಲ್ಲ, ಸತ್ತೂ ಇರಲಿಲ್ಲ; ಅಂತರಿಕ್ಷವೂ ಇರಲಿಲ್ಲ, ಅದರಾಚೆಯ ಆಕಾಶವೂ ಇರಲಿಲ್ಲ. ಏನು ಮುಚ್ಚಿತ್ತು? ಎಲ್ಲಿ? ಯಾರ ರಕ್ಷಣೆಯಲ್ಲಿ? ಅಗಾಧವಾದ ಆಳದ ಜಲವಿತ್ತೇ?'],
    w: [['नासत्', 'na + asat, “not non-being” — the hymn begins by denying both opposites.', 'ನ + ಅಸತ್, "ಅಸತ್ ಅಲ್ಲ" — ಸೂಕ್ತ ಎರಡೂ ವಿರುದ್ಧಗಳನ್ನು ನಿರಾಕರಿಸುವುದರಿಂದ ಆರಂಭ.'],
      ['आसीत्', '“was” — imperfect of √as; the whole verse is set in a time before time.', '"ಇತ್ತು" — √ಅಸ್ ಧಾತುವಿನ ಲಙ್ (ಭೂತಕಾಲ); ಕಾಲಕ್ಕಿಂತ ಮೊದಲಿನ ಕಾಲದ ವರ್ಣನೆ.'],
      ['गहनं गभीरम्', '“impenetrable, deep” — two near-synonyms for the unfathomable.', '"ಅಭೇದ್ಯ, ಆಳ" — ಅಗಾಧತೆಯನ್ನು ಸೂಚಿಸುವ ಎರಡು ಸಮಾನಾರ್ಥಕ ಪದಗಳು.']],
    u: ['The Nāsadīya Sūkta, the hymn of creation. It answers with questions, and ends by doubting whether even the overseer in the highest heaven knows. It is admired across the world as the Veda’s boldest philosophy.', 'ನಾಸದೀಯ ಸೂಕ್ತ — ಸೃಷ್ಟಿಸೂಕ್ತ. ಉತ್ತರಗಳ ಬದಲು ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳುತ್ತದೆ; ಪರಮವ್ಯೋಮದಲ್ಲಿರುವ ಅಧ್ಯಕ್ಷನಿಗಾದರೂ ತಿಳಿದಿದೆಯೇ ಎಂಬ ಸಂಶಯದಿಂದ ಕೊನೆಗೊಳ್ಳುತ್ತದೆ. ವೇದದ ಅತ್ಯಂತ ದಿಟ್ಟ ತತ್ತ್ವಚಿಂತನೆ ಎಂದು ಜಗತ್ತಿನಾದ್ಯಂತ ಮೆಚ್ಚುಗೆ.'] },
  { at: 'rv 10.129.7',
    m: ['From where this creation came, whether it was made or not — he who watches over it in the highest heaven, he surely knows; or perhaps he does not know.', 'ಈ ಸೃಷ್ಟಿ ಎಲ್ಲಿಂದ ಬಂತು, ಅದನ್ನು ಯಾರಾದರೂ ಮಾಡಿದರೋ ಇಲ್ಲವೋ — ಪರಮವ್ಯೋಮದಲ್ಲಿ ಅದನ್ನು ಕಾಯುವವನು ಖಂಡಿತ ಬಲ್ಲ; ಅಥವಾ ಅವನಿಗೂ ತಿಳಿಯದಿರಬಹುದು.'],
    w: [['विसृष्टिः', '“emanation, creation” — vi + √sṛj, to let go forth.', '"ಹೊರಹೊಮ್ಮುವಿಕೆ, ಸೃಷ್ಟಿ" — ವಿ + √ಸೃಜ್ (ಹೊರಬಿಡು).'],
      ['अध्यक्षः', '“overseer” — adhi + akṣa, one whose eye is over all.', '"ಅಧ್ಯಕ್ಷ" — ಅಧಿ + ಅಕ್ಷ, ಎಲ್ಲದರ ಮೇಲೆ ಕಣ್ಣಿಟ್ಟವನು.'],
      ['व्योमन्', '“in heaven” — a Vedic locative without its ending (classical vyomani).', '"ಆಕಾಶದಲ್ಲಿ" — ವಿಭಕ್ತಿಪ್ರತ್ಯಯವಿಲ್ಲದ ವೈದಿಕ ಸಪ್ತಮೀ (ಲೌಕಿಕದಲ್ಲಿ ವ್ಯೋಮನಿ).']],
    u: ['The closing ṛk of the Nāsadīya Sūkta. Its final “perhaps he does not know” is a rare moment of humility before the mystery, valued by thinkers ancient and modern.', 'ನಾಸದೀಯ ಸೂಕ್ತದ ಕೊನೆಯ ಋಕ್. "ಅವನಿಗೂ ತಿಳಿಯದಿರಬಹುದು" ಎಂಬ ಅಂತ್ಯ ರಹಸ್ಯದ ಮುಂದೆ ವಿನಮ್ರತೆಯ ಅಪರೂಪದ ಕ್ಷಣ; ಪ್ರಾಚೀನ ಮತ್ತು ಆಧುನಿಕ ಚಿಂತಕರು ಮೆಚ್ಚಿದ್ದು.'] },
  { at: 'rv 10.191.2',
    m: ['Go together, speak together, let your minds be of one accord, as the gods of old, of one mind, took their shares.', 'ಒಟ್ಟಿಗೆ ನಡೆಯಿರಿ, ಒಟ್ಟಿಗೆ ಮಾತನಾಡಿರಿ, ನಿಮ್ಮ ಮನಸ್ಸುಗಳು ಒಮ್ಮತದಿಂದಿರಲಿ — ಹಿಂದಿನ ದೇವತೆಗಳು ಒಮ್ಮನಸ್ಸಿನಿಂದ ತಮ್ಮ ಪಾಲನ್ನು ಸ್ವೀಕರಿಸಿದಂತೆ.'],
    w: [['सं गच्छध्वम्', '“go together” — saṃ + √gam, 2nd person plural imperative, middle.', '"ಒಟ್ಟಿಗೆ ನಡೆಯಿರಿ" — ಸಂ + √ಗಮ್, ಮಧ್ಯಮಪುರುಷ ಬಹುವಚನ, ಲೋಟ್, ಆತ್ಮನೇಪದ.'],
      ['सं वदध्वम्', '“speak together” — the same prefix saṃ ties every verb of the verse.', '"ಒಟ್ಟಿಗೆ ಮಾತನಾಡಿರಿ" — ಸಂ ಉಪಸರ್ಗ ಮಂತ್ರದ ಪ್ರತಿ ಕ್ರಿಯಾಪದವನ್ನು ಕಟ್ಟುತ್ತದೆ.'],
      ['जानताम्', '“let them know, agree” — 3rd person plural imperative of √jñā.', '"ತಿಳಿಯಲಿ, ಒಪ್ಪಲಿ" — √ಜ್ಞಾ ಧಾತು, ಪ್ರಥಮಪುರುಷ ಬಹುವಚನ, ಲೋಟ್.']],
    u: ['From the Saṃjñāna (or Aikamatya) Sūkta, the last hymn of the Ṛgveda, recited to close a recitation of the Saṃhitā and in prayers for unity at meetings and in families.', 'ಋಗ್ವೇದದ ಕೊನೆಯ ಸೂಕ್ತವಾದ ಸಂಜ್ಞಾನ (ಐಕಮತ್ಯ) ಸೂಕ್ತದಿಂದ; ಸಂಹಿತಾಪಾರಾಯಣದ ಸಮಾಪ್ತಿಯಲ್ಲಿ, ಸಭೆ ಮತ್ತು ಕುಟುಂಬಗಳ ಐಕ್ಯಕ್ಕಾಗಿ ಪಠಣ.'] },
  { at: 'rv 10.191.4',
    m: ['Common be your intention, common your hearts, common your minds, so that you may live well together.', 'ನಿಮ್ಮ ಸಂಕಲ್ಪ ಒಂದಾಗಿರಲಿ, ನಿಮ್ಮ ಹೃದಯಗಳು ಒಂದಾಗಿರಲಿ, ನಿಮ್ಮ ಮನಸ್ಸು ಒಂದಾಗಿರಲಿ — ನೀವು ಸುಖವಾಗಿ ಒಟ್ಟಿಗೆ ಬಾಳುವಂತೆ.'],
    w: [['समानी', '“common, the same” — the word repeats to bind the community.', '"ಸಮಾನ, ಒಂದೇ" — ಸಮುದಾಯವನ್ನು ಬಂಧಿಸಲು ಪದ ಪುನರಾವರ್ತಿತ.'],
      ['आकूतिः', '“intention, purpose” — ā + √kū.', '"ಸಂಕಲ್ಪ, ಉದ್ದೇಶ" — ಆ + √ಕೂ.'],
      ['सुसहासति', 'su-saha asati: “that there may be good togetherness” — asati is a Vedic subjunctive of √as.', 'ಸುಸಹ ಅಸತಿ: "ಒಳ್ಳೆಯ ಸಹಬಾಳ್ವೆ ಇರುವಂತೆ" — ಅಸತಿ √ಅಸ್ ಧಾತುವಿನ ವೈದಿಕ ಲೇಟ್ ರೂಪ.']],
    u: ['The very last ṛk of the Ṛgveda. That the Veda ends with a prayer for shared purpose has made it a favourite at assemblies, weddings and the closing of study.', 'ಋಗ್ವೇದದ ಅಂತಿಮ ಋಕ್. ವೇದ ಸಮಾನ ಉದ್ದೇಶದ ಪ್ರಾರ್ಥನೆಯಿಂದ ಮುಗಿಯುವುದರಿಂದ ಸಭೆಗಳು, ವಿವಾಹಗಳು, ಅಧ್ಯಯನದ ಸಮಾಪ್ತಿಯಲ್ಲಿ ಪ್ರಿಯವಾದ ಮಂತ್ರ.'] },
  { at: 'rv 10.90.1',
    m: ['The Puruṣa has a thousand heads, a thousand eyes, a thousand feet. Covering the earth on every side, he stood beyond it by ten fingers.', 'ಪುರುಷನಿಗೆ ಸಾವಿರ ತಲೆಗಳು, ಸಾವಿರ ಕಣ್ಣುಗಳು, ಸಾವಿರ ಪಾದಗಳು. ಭೂಮಿಯನ್ನು ಎಲ್ಲೆಡೆ ಆವರಿಸಿ, ಅದನ್ನು ಹತ್ತು ಅಂಗುಲ ಮೀರಿ ನಿಂತನು.'],
    w: [['सहस्रशीर्षा', '“thousand-headed” — a bahuvrīhi compound: one who has a thousand heads.', '"ಸಾವಿರ ತಲೆಯುಳ್ಳವನು" — ಬಹುವ್ರೀಹಿ ಸಮಾಸ.'],
      ['दशाङ्गुलम्', '“ten fingers’ breadth” — he exceeds the world, however measured.', '"ಹತ್ತು ಅಂಗುಲ" — ಹೇಗೆ ಅಳೆದರೂ ಜಗತ್ತನ್ನು ಮೀರಿದವನು.'],
      ['अत्यतिष्ठत्', '“stood beyond” — ati + √sthā, imperfect.', '"ಮೀರಿ ನಿಂತನು" — ಅತಿ + √ಸ್ಥಾ, ಲಙ್.']],
    u: ['First ṛk of the Puruṣa Sūkta, recited in pūjā (often one ṛk with each of the sixteen upacāras), abhiṣeka and homa. “Thousand” means countless: all heads, eyes and feet are his.', 'ಪುರುಷಸೂಕ್ತದ ಮೊದಲ ಋಕ್; ಪೂಜೆ (ಷೋಡಶೋಪಚಾರಗಳಲ್ಲಿ ಪ್ರತಿ ಉಪಚಾರಕ್ಕೆ ಒಂದು ಋಕ್), ಅಭಿಷೇಕ, ಹೋಮಗಳಲ್ಲಿ ಪಠಣ. "ಸಾವಿರ" ಎಂದರೆ ಅಸಂಖ್ಯ: ಎಲ್ಲ ತಲೆ, ಕಣ್ಣು, ಪಾದಗಳೂ ಅವನವೇ.'] },
  { at: 'rv 10.90.16',
    m: ['By sacrifice the gods sacrificed to the sacrifice; these were the first ordinances. These great powers reached the firmament, where the ancient gods, the Sādhyas, dwell.', 'ದೇವತೆಗಳು ಯಜ್ಞದಿಂದ ಯಜ್ಞವನ್ನು ಆರಾಧಿಸಿದರು; ಅವೇ ಮೊದಲ ಧರ್ಮಗಳು. ಆ ಮಹಿಮೆಗಳು ಪ್ರಾಚೀನ ಸಾಧ್ಯದೇವತೆಗಳಿರುವ ಸ್ವರ್ಗವನ್ನು ಸೇರಿದವು.'],
    w: [['यज्ञेन यज्ञम्', '“by sacrifice … the sacrifice” — instrument and object are the same: the sacrifice offers itself.', '"ಯಜ್ಞದಿಂದ … ಯಜ್ಞವನ್ನು" — ಸಾಧನವೂ ಕರ್ಮವೂ ಒಂದೇ: ಯಜ್ಞ ತನ್ನನ್ನು ತಾನೇ ಅರ್ಪಿಸುತ್ತದೆ.'],
      ['अयजन्त', '“they worshipped” — imperfect, 3rd person plural, middle, of √yaj.', '"ಆರಾಧಿಸಿದರು" — √ಯಜ್, ಲಙ್, ಪ್ರಥಮಪುರುಷ ಬಹುವಚನ, ಆತ್ಮನೇಪದ.'],
      ['धर्माणि', '“ordinances, supports” — Vedic dharman, that which holds.', '"ಧರ್ಮಗಳು, ಆಧಾರಗಳು" — ವೈದಿಕ ಧರ್ಮನ್, ಧರಿಸುವುದು.']],
    u: ['The closing ṛk of the Puruṣa Sūkta, also part of the Mantrapuṣpam. It turns the hymn into a principle: the world is sustained by offering, and the first dharma was sacrifice.', 'ಪುರುಷಸೂಕ್ತದ ಕೊನೆಯ ಋಕ್; ಮಂತ್ರಪುಷ್ಪದಲ್ಲೂ ಇದೆ. ಜಗತ್ತು ಅರ್ಪಣೆಯಿಂದ ನಿಲ್ಲುತ್ತದೆ, ಮೊದಲ ಧರ್ಮ ಯಜ್ಞ — ಎಂಬ ತತ್ತ್ವವಾಗಿ ಸೂಕ್ತವನ್ನು ಮುಗಿಸುತ್ತದೆ.'] },
  { at: 'rv 2.23.1',
    m: ['We invoke you, lord of the hosts among the hosts, poet of poets, of highest fame, eldest king of prayers, O Brahmaṇaspati. Hear us, and with your help sit in your seat.', 'ಗಣಗಳ ಒಡೆಯನಾದ ಗಣಪತಿ, ಕವಿಗಳ ಕವಿ, ಅತ್ಯಂತ ಕೀರ್ತಿವಂತ, ಮಂತ್ರಗಳ ಜ್ಯೇಷ್ಠರಾಜ, ಓ ಬ್ರಹ್ಮಣಸ್ಪತಿ, ನಿನ್ನನ್ನು ಆಹ್ವಾನಿಸುತ್ತೇವೆ. ನಮ್ಮ ಮಾತು ಕೇಳಿ, ರಕ್ಷಣೆಯೊಂದಿಗೆ ನಿನ್ನ ಆಸನದಲ್ಲಿ ಕುಳಿತುಕೋ.'],
    w: [['गणानाम्', '“of the hosts” — genitive plural of gaṇa, a troop or company.', '"ಗಣಗಳ" — ಗಣ ಪದದ ಷಷ್ಠೀ ಬಹುವಚನ.'],
      ['कविं कवीनाम्', '“poet of poets” — the genitive of the same word marks the highest of its kind.', '"ಕವಿಗಳ ಕವಿ" — ಅದೇ ಪದದ ಷಷ್ಠಿ ಶ್ರೇಷ್ಠತೆಯನ್ನು ಸೂಚಿಸುತ್ತದೆ.'],
      ['सीद', '“sit” — imperative of √sad; the god is asked to take his seat at the rite.', '"ಕುಳಿತುಕೋ" — √ಸದ್ ಧಾತುವಿನ ಲೋಟ್; ಯಜ್ಞದಲ್ಲಿ ಆಸನ ಸ್ವೀಕರಿಸಲು ಪ್ರಾರ್ಥನೆ.']],
    u: ['Addressed to Brahmaṇaspati, this ṛk is used everywhere to invoke Gaṇapati at the start of a pūjā, homa or any undertaking, so that it proceeds without obstacles.', 'ಬ್ರಹ್ಮಣಸ್ಪತಿಗೆ ಉದ್ದೇಶಿತವಾದ ಈ ಋಕ್ ಪೂಜೆ, ಹೋಮ, ಯಾವುದೇ ಕಾರ್ಯದ ಆರಂಭದಲ್ಲಿ ಗಣಪತಿಯ ಆವಾಹನೆಗಾಗಿ ಎಲ್ಲೆಡೆ ಬಳಕೆ — ಕಾರ್ಯ ನಿರ್ವಿಘ್ನವಾಗಲೆಂದು.'] },
  { at: 'rv 1.22.20',
    m: ['That highest step of Viṣṇu the wise always see, like an eye spread out in the sky.', 'ವಿಷ್ಣುವಿನ ಆ ಪರಮಪದವನ್ನು ಜ್ಞಾನಿಗಳು ಸದಾ ಕಾಣುತ್ತಾರೆ — ಆಕಾಶದಲ್ಲಿ ಹರಡಿದ ಕಣ್ಣಿನಂತೆ.'],
    w: [['परमं पदम्', '“the highest step, the highest abode” — pada is both footstep and place.', '"ಪರಮ ಹೆಜ್ಜೆ, ಪರಮ ಸ್ಥಾನ" — ಪದ ಎಂದರೆ ಹೆಜ್ಜೆಯೂ ಸ್ಥಾನವೂ.'],
      ['सूरयः', '“the wise, the patrons” — nominative plural of sūri.', '"ಜ್ಞಾನಿಗಳು" — ಸೂರಿ ಪದದ ಪ್ರಥಮಾ ಬಹುವಚನ.'],
      ['दिवीव', 'divi iva, “as in the sky” — iva, like, after the word it qualifies.', 'ದಿವಿ ಇವ, "ಆಕಾಶದಲ್ಲಿರುವಂತೆ" — ಇವ (ಹಾಗೆ) ಹೋಲಿಸುವ ಪದದ ನಂತರ.']],
    u: ['Recited in the worship of Viṣṇu and quoted again and again in Vaiṣṇava thought: paramaṃ padam became the name of the final goal, the abode from which there is no return.', 'ವಿಷ್ಣುಪೂಜೆಯಲ್ಲಿ ಪಠಣ; ವೈಷ್ಣವ ಚಿಂತನೆಯಲ್ಲಿ ಮತ್ತೆ ಮತ್ತೆ ಉಲ್ಲೇಖ: "ಪರಮಂ ಪದಮ್" ಮರಳಿ ಬಾರದ ಅಂತಿಮ ಗುರಿಯ ಹೆಸರಾಯಿತು.'] },
  { at: 'rv 1.90.9',
    m: ['Be gracious to us, Mitra; gracious, Varuṇa; gracious to us be Aryaman; gracious Indra and Bṛhaspati; gracious to us Viṣṇu of the wide stride.', 'ಮಿತ್ರನು ನಮಗೆ ಶುಭಕರನಾಗಲಿ, ವರುಣನು ಶುಭಕರನಾಗಲಿ, ಅರ್ಯಮನು ಶುಭಕರನಾಗಲಿ; ಇಂದ್ರ-ಬೃಹಸ್ಪತಿಗಳು ಶುಭಕರರಾಗಲಿ; ವಿಶಾಲ ಹೆಜ್ಜೆಯ ವಿಷ್ಣು ಶುಭಕರನಾಗಲಿ.'],
    w: [['शं नः', '“weal to us, for our welfare” — śam is an indeclinable of peace and good fortune.', '"ನಮಗೆ ಶುಭ" — ಶಮ್ ಶಾಂತಿ ಮತ್ತು ಕಲ್ಯಾಣ ಸೂಚಿಸುವ ಅವ್ಯಯ.'],
      ['भवतु', '“may he be” — imperative of √bhū, understood with every name.', '"ಆಗಲಿ" — √ಭೂ ಲೋಟ್; ಪ್ರತಿ ಹೆಸರಿನೊಂದಿಗೆ ಅನ್ವಯ.'],
      ['उरुक्रमः', '“wide-striding” — uru + krama, Viṣṇu of the three steps.', '"ವಿಶಾಲವಾಗಿ ಹೆಜ್ಜೆ ಇಡುವವನು" — ಉರು + ಕ್ರಮ; ತ್ರಿವಿಕ್ರಮ ವಿಷ್ಣು.']],
    u: ['Familiar as the opening of the Taittirīya Upaniṣad’s śānti pāṭha, recited before Vedic study and in daily prayers.', 'ತೈತ್ತಿರೀಯ ಉಪನಿಷತ್ತಿನ ಶಾಂತಿಪಾಠದ ಆರಂಭವಾಗಿ ಪರಿಚಿತ; ವೇದಾಧ್ಯಯನದ ಮೊದಲು ಮತ್ತು ನಿತ್ಯಪ್ರಾರ್ಥನೆಗಳಲ್ಲಿ ಪಠಣ.'] },
  { at: 'rv 1.89.8',
    m: ['May we hear with our ears what is good, O gods; may we see with our eyes what is good, O worshipful ones. With steady limbs and bodies, praising, may we enjoy the life the gods have set for us.', 'ದೇವತೆಗಳೇ, ಕಿವಿಗಳಿಂದ ಶುಭವನ್ನು ಕೇಳೋಣ; ಯಜ್ಞಾರ್ಹರೇ, ಕಣ್ಣುಗಳಿಂದ ಶುಭವನ್ನು ನೋಡೋಣ. ದೃಢವಾದ ಅಂಗ-ದೇಹಗಳಿಂದ ಸ್ತುತಿಸುತ್ತ ದೇವತೆಗಳು ನಮಗಿತ್ತ ಆಯುಸ್ಸನ್ನು ಅನುಭವಿಸೋಣ.'],
    w: [['कर्णेभिः', '“with the ears” — the old Vedic instrumental plural in -ebhiḥ (classical karṇaiḥ).', '"ಕಿವಿಗಳಿಂದ" — ವೈದಿಕ ತೃತೀಯಾ ಬಹುವಚನ -ಏಭಿಃ (ಲೌಕಿಕದಲ್ಲಿ ಕರ್ಣೈಃ).'],
      ['शृणुयाम', '“may we hear” — optative, 1st person plural, of √śru.', '"ಕೇಳೋಣ" — √ಶ್ರು, ವಿಧಿಲಿಙ್, ಉತ್ತಮಪುರುಷ ಬಹುವಚನ.'],
      ['व्यशेम', '“may we attain, enjoy” — vi + √aś, optative.', '"ಪಡೆಯೋಣ, ಅನುಭವಿಸೋಣ" — ವಿ + √ಅಶ್, ವಿಧಿಲಿಙ್.']],
    u: ['The śānti pāṭha of the Atharvaveda Upaniṣads (Muṇḍaka, Praśna, Māṇḍūkya), recited before and after study. A prayer to use the senses well and live the full span in health.', 'ಅಥರ್ವವೇದದ ಉಪನಿಷತ್ತುಗಳ (ಮುಂಡಕ, ಪ್ರಶ್ನ, ಮಾಂಡೂಕ್ಯ) ಶಾಂತಿಪಾಠ; ಅಧ್ಯಯನದ ಮೊದಲು ಮತ್ತು ನಂತರ ಪಠಣ. ಇಂದ್ರಿಯಗಳ ಸದ್ಬಳಕೆ, ಪೂರ್ಣ ಆಯುಸ್ಸು ಆರೋಗ್ಯದಿಂದ — ಎಂಬ ಪ್ರಾರ್ಥನೆ.'] },
  { at: 'rv 7.66.16',
    m: ['That eye, set by the gods, rises bright in the east. May we see a hundred autumns; may we live a hundred autumns.', 'ದೇವತೆಗಳು ಇಟ್ಟ ಆ ಕಣ್ಣು ಪೂರ್ವದಲ್ಲಿ ಪ್ರಕಾಶಮಾನವಾಗಿ ಉದಯಿಸುತ್ತಿದೆ. ನೂರು ಶರತ್ತುಗಳನ್ನು ನೋಡೋಣ; ನೂರು ಶರತ್ತುಗಳು ಬಾಳೋಣ.'],
    w: [['चक्षुः', '“eye” — the sun as the eye of the gods.', '"ಕಣ್ಣು" — ದೇವತೆಗಳ ಕಣ್ಣಾದ ಸೂರ್ಯ.'],
      ['शरदः शतम्', '“a hundred autumns” — years counted by autumns, the season of harvest.', '"ನೂರು ಶರತ್ತುಗಳು" — ವರ್ಷಗಳನ್ನು ಸುಗ್ಗಿಯ ಋತುವಾದ ಶರತ್ತಿನಿಂದ ಎಣಿಕೆ.'],
      ['पश्येम … जीवेम', '“may we see … may we live” — optatives of √paś and √jīv.', '"ನೋಡೋಣ … ಬಾಳೋಣ" — √ಪಶ್, √ಜೀವ್ ಧಾತುಗಳ ವಿಧಿಲಿಙ್.']],
    u: ['Said in the Sūrya upasthāna of sandhyāvandana, and as a blessing on birthdays. The Vājasaneyi version (36.24) adds hearing, speaking and freedom from want for a hundred years.', 'ಸಂಧ್ಯಾವಂದನೆಯ ಸೂರ್ಯೋಪಸ್ಥಾನದಲ್ಲಿ, ಜನ್ಮದಿನದ ಆಶೀರ್ವಾದವಾಗಿ ಪಠಣ. ವಾಜಸನೇಯಿ ಪಾಠ (೩೬.೨೪) ನೂರು ವರ್ಷ ಕೇಳುವುದು, ಮಾತನಾಡುವುದು, ದೈನ್ಯವಿಲ್ಲದಿರುವುದನ್ನೂ ಸೇರಿಸುತ್ತದೆ.'] },
  { at: 'rv 10.9.1',
    m: ['You, Waters, are the source of joy; give us strength, for great delight and for clear sight.', 'ಜಲಗಳೇ, ನೀವು ಸುಖದ ಮೂಲ; ಮಹಾ ಆನಂದಕ್ಕಾಗಿ, ಸ್ಪಷ್ಟ ದೃಷ್ಟಿಗಾಗಿ ನಮಗೆ ಶಕ್ತಿಯನ್ನು ನೀಡಿರಿ.'],
    w: [['मयोभुवः', '“sources of delight” — mayas (joy) + bhū (being, source).', '"ಸುಖದ ಮೂಲಗಳು" — ಮಯಸ್ (ಆನಂದ) + ಭೂ.'],
      ['दधातन', '“give, place” — a Vedic imperative 2nd plural in -tana (classical dhatta).', '"ಕೊಡಿರಿ, ಇರಿಸಿರಿ" — -ತನ ಅಂತ್ಯದ ವೈದಿಕ ಲೋಟ್ ಮಧ್ಯಮಪುರುಷ ಬಹುವಚನ (ಲೌಕಿಕದಲ್ಲಿ ಧತ್ತ).'],
      ['चक्षसे', '“for seeing” — a dative infinitive.', '"ನೋಡುವುದಕ್ಕಾಗಿ" — ಚತುರ್ಥೀ ತುಮರ್ಥಕ ರೂಪ.']],
    u: ['Āpo hi ṣṭhā: the mārjana mantras of sandhyāvandana. Water is sprinkled on the head as each pāda is said; the same verses consecrate water in pūjās and purifications.', 'ಆಪೋ ಹಿ ಷ್ಠಾ: ಸಂಧ್ಯಾವಂದನೆಯ ಮಾರ್ಜನ ಮಂತ್ರಗಳು. ಪ್ರತಿ ಪಾದಕ್ಕೆ ತಲೆಯ ಮೇಲೆ ನೀರು ಪ್ರೋಕ್ಷಣೆ; ಪೂಜೆ, ಶುದ್ಧೀಕರಣಗಳಲ್ಲಿ ಜಲಾಭಿಮಂತ್ರಣಕ್ಕೂ ಇವೇ ಮಂತ್ರಗಳು.'] },
  { at: 'rv 1.50.1',
    m: ['His rays bear up the god who knows all beings, Sūrya, so that all may see.', 'ಎಲ್ಲ ಜೀವಿಗಳನ್ನು ಬಲ್ಲ ಸೂರ್ಯದೇವನನ್ನು, ಎಲ್ಲರೂ ನೋಡುವಂತೆ, ಅವನ ಕಿರಣಗಳು ಮೇಲಕ್ಕೆ ಹೊತ್ತೊಯ್ಯುತ್ತವೆ.'],
    w: [['जातवेदसम्', '“knower of all that is born” — jāta + vedas; usually Agni, here the sun.', '"ಹುಟ್ಟಿದ ಎಲ್ಲವನ್ನೂ ಬಲ್ಲವನು" — ಜಾತ + ವೇದಸ್; ಸಾಮಾನ್ಯವಾಗಿ ಅಗ್ನಿ, ಇಲ್ಲಿ ಸೂರ್ಯ.'],
      ['केतवः', '“rays, banners” — the signs that announce him.', '"ಕಿರಣಗಳು, ಧ್ವಜಗಳು" — ಅವನನ್ನು ಸಾರುವ ಚಿಹ್ನೆಗಳು.'],
      ['दृशे', '“to see, for seeing” — a dative infinitive of √dṛś.', '"ನೋಡಲು" — √ದೃಶ್ ಧಾತುವಿನ ಚತುರ್ಥೀ ತುಮರ್ಥಕ.']],
    u: ['Recited in the Sūrya upasthāna of Ṛgvedin sandhyāvandana and in Sūrya worship; the hymn continues with prayers that the sun remove heart-ache and pallor.', 'ಋಗ್ವೇದಿಗಳ ಸಂಧ್ಯಾವಂದನೆಯ ಸೂರ್ಯೋಪಸ್ಥಾನದಲ್ಲಿ, ಸೂರ್ಯಾರಾಧನೆಯಲ್ಲಿ ಪಠಣ; ಮುಂದಿನ ಋಕ್ಕುಗಳು ಹೃದ್ರೋಗ, ಪಾಂಡುರೋಗ ನಿವಾರಣೆಗೆ ಪ್ರಾರ್ಥಿಸುತ್ತವೆ.'] },
  { at: 'rv 1.115.1',
    m: ['The bright face of the gods has risen, the eye of Mitra, Varuṇa and Agni. It has filled heaven, earth and the space between: Sūrya is the self of all that moves and all that stands.', 'ದೇವತೆಗಳ ಉಜ್ಜ್ವಲ ಮುಖ ಉದಯಿಸಿದೆ — ಮಿತ್ರ, ವರುಣ, ಅಗ್ನಿಯರ ಕಣ್ಣು. ಆಕಾಶ, ಭೂಮಿ, ಅಂತರಿಕ್ಷಗಳನ್ನು ತುಂಬಿದೆ; ಸೂರ್ಯನು ಚಲಿಸುವ ಮತ್ತು ನಿಂತಿರುವ ಎಲ್ಲದರ ಆತ್ಮ.'],
    w: [['चित्रम्', '“bright, wonderful, many-hued”.', '"ಉಜ್ಜ್ವಲ, ಅದ್ಭುತ, ಬಹುವರ್ಣ".'],
      ['उदगात्', '“has risen” — ud + √i, root aorist.', '"ಉದಯಿಸಿದೆ" — ಉತ್ + √ಇ, ಲುಙ್.'],
      ['तस्थुषः', '“of what stands still” — genitive of the perfect participle of √sthā.', '"ನಿಂತಿರುವುದರ" — √ಸ್ಥಾ ಧಾತುವಿನ ಲಿಟ್ ಕೃದಂತದ ಷಷ್ಠಿ.']],
    u: ['Part of the Sūrya upasthāna and of Sūrya worship. “Sūrya ātmā jagatas tasthuṣaś ca” is an early statement that one light is the inner self of the whole world.', 'ಸೂರ್ಯೋಪಸ್ಥಾನ ಮತ್ತು ಸೂರ್ಯಾರಾಧನೆಯ ಭಾಗ. "ಸೂರ್ಯ ಆತ್ಮಾ ಜಗತಸ್ತಸ್ಥುಷಶ್ಚ" — ಒಂದೇ ಬೆಳಕು ಇಡೀ ಜಗತ್ತಿನ ಆಂತರಿಕ ಆತ್ಮ ಎಂಬ ಆರಂಭಿಕ ಘೋಷಣೆ.'] },
  { at: 'rv 10.121.1',
    m: ['In the beginning arose the Golden Germ; once born, he was the one lord of what exists. He upheld the earth and this sky. To which god shall we offer our worship?', 'ಆದಿಯಲ್ಲಿ ಹಿರಣ್ಯಗರ್ಭನು ಉದಿಸಿದನು; ಹುಟ್ಟಿದೊಡನೆ ಇರುವ ಎಲ್ಲದರ ಏಕೈಕ ಒಡೆಯನಾದನು. ಅವನು ಭೂಮಿಯನ್ನೂ ಈ ಆಕಾಶವನ್ನೂ ಹಿಡಿದಿಟ್ಟನು. ಯಾವ ದೇವನಿಗೆ ಹವಿಸ್ಸಿನಿಂದ ಆರಾಧಿಸೋಣ?'],
    w: [['हिरण्यगर्भः', '“golden germ / golden womb” — the first-born source of creation.', '"ಹಿರಣ್ಯದ ಗರ್ಭ" — ಸೃಷ್ಟಿಯ ಪ್ರಥಮಜ ಮೂಲ.'],
      ['समवर्तत', '“came into being” — sam + √vṛt, imperfect, middle.', '"ಉಂಟಾದನು" — ಸಮ್ + √ವೃತ್, ಲಙ್, ಆತ್ಮನೇಪದ.'],
      ['कस्मै … विधेम', '“to whom … shall we worship?” — kasmai, dative of ka; vidhema, optative of √vidh.', '"ಯಾರಿಗೆ … ಆರಾಧಿಸೋಣ?" — ಕಸ್ಮೈ, ಕ ಪದದ ಚತುರ್ಥಿ; ವಿಧೇಮ, √ವಿಧ್ ವಿಧಿಲಿಙ್.']],
    u: ['The Hiraṇyagarbha Sūkta. Its refrain was read as a name: Ka, “Who”, became Prajāpati, and offerings are made “to Ka”. Hiraṇyagarbha became a name of the creator in later thought.', 'ಹಿರಣ್ಯಗರ್ಭ ಸೂಕ್ತ. ಪಲ್ಲವಿಯ ಪ್ರಶ್ನೆಯನ್ನು ಹೆಸರಾಗಿ ಓದಲಾಯಿತು: "ಕ" (ಯಾರು) ಪ್ರಜಾಪತಿಯಾದನು; "ಕಾಯ" ಎಂದು ಹವಿಸ್ಸು. ಮುಂದಿನ ಚಿಂತನೆಯಲ್ಲಿ ಹಿರಣ್ಯಗರ್ಭ ಸೃಷ್ಟಿಕರ್ತನ ಹೆಸರು.'] },
  { at: 'rv 10.125.1',
    m: ['I move with the Rudras and the Vasus, with the Ādityas and all the gods. I uphold Mitra and Varuṇa, Indra and Agni, and the two Aśvins.', 'ನಾನು ರುದ್ರರೊಂದಿಗೆ, ವಸುಗಳೊಂದಿಗೆ, ಆದಿತ್ಯರೊಂದಿಗೆ, ವಿಶ್ವೇದೇವರೊಂದಿಗೆ ಸಂಚರಿಸುತ್ತೇನೆ. ಮಿತ್ರ-ವರುಣರನ್ನೂ ಇಂದ್ರ-ಅಗ್ನಿಯರನ್ನೂ ಅಶ್ವಿನೀದೇವತೆಗಳನ್ನೂ ಧರಿಸಿದ್ದೇನೆ.'],
    w: [['रुद्रेभिः', '“with the Rudras” — Vedic instrumental plural in -ebhiḥ.', '"ರುದ್ರರೊಂದಿಗೆ" — ವೈದಿಕ ತೃತೀಯಾ ಬಹುವಚನ -ಏಭಿಃ.'],
      ['चरामि', '“I move, I go about” — 1st person singular present of √car.', '"ಸಂಚರಿಸುತ್ತೇನೆ" — √ಚರ್, ಉತ್ತಮಪುರುಷ ಏಕವಚನ, ಲಟ್.'],
      ['बिभर्मि', '“I bear, I uphold” — reduplicated present of √bhṛ.', '"ಧರಿಸುತ್ತೇನೆ" — √ಭೃ ಧಾತುವಿನ ದ್ವಿರುಕ್ತ ಲಟ್.']],
    u: ['The Devī Sūkta (Vāk Sūkta), spoken by the goddess Vāk in the first person. It is recited in Devī worship, in Navarātri and with the Devī Māhātmya.', 'ದೇವೀಸೂಕ್ತ (ವಾಕ್ಸೂಕ್ತ) — ವಾಕ್ ದೇವಿ ಉತ್ತಮಪುರುಷದಲ್ಲಿ ಹೇಳುವುದು. ದೇವೀಪೂಜೆ, ನವರಾತ್ರಿ, ದೇವೀಮಾಹಾತ್ಮ್ಯ ಪಾರಾಯಣದೊಂದಿಗೆ ಪಠಣ.'] },
  { at: 'rv 10.125.3',
    m: ['I am the queen, the gatherer of riches, the knowing one, first of those worthy of worship. The gods have set me in many places, abiding in many forms, entering into many.', 'ನಾನು ರಾಣಿ, ಸಂಪತ್ತುಗಳನ್ನು ಒಟ್ಟುಗೂಡಿಸುವವಳು, ಜ್ಞಾನವತಿ, ಯಜ್ಞಾರ್ಹರಲ್ಲಿ ಮೊದಲನೆಯವಳು. ದೇವತೆಗಳು ನನ್ನನ್ನು ಅನೇಕ ಸ್ಥಳಗಳಲ್ಲಿ ಇರಿಸಿದ್ದಾರೆ — ಅನೇಕ ರೂಪಗಳಲ್ಲಿ ನೆಲೆಸಿ, ಅನೇಕರಲ್ಲಿ ಪ್ರವೇಶಿಸಿದವಳು.'],
    w: [['राष्ट्री', '“queen, ruler of the realm” — feminine of rāṣṭra, kingdom.', '"ರಾಣಿ, ರಾಷ್ಟ್ರದ ಒಡತಿ".'],
      ['चिकितुषी', '“she who knows” — feminine perfect participle of √cit.', '"ಅರಿತವಳು" — √ಚಿತ್ ಧಾತುವಿನ ಲಿಟ್ ಕೃದಂತ, ಸ್ತ್ರೀಲಿಂಗ.'],
      ['सङ्गमनी', '“who brings together” — saṃ + √gam with the agent suffix -anī.', '"ಒಂದುಗೂಡಿಸುವವಳು" — ಸಮ್ + √ಗಮ್ + ಅನೀ (ಕರ್ತೃ).']],
    u: ['From the Devī Sūkta. The goddess is one power present in all; Śākta tradition reads the hymn as the Veda’s own statement of the Devī.', 'ದೇವೀಸೂಕ್ತದಿಂದ. ದೇವಿ ಎಲ್ಲರಲ್ಲೂ ಇರುವ ಒಂದೇ ಶಕ್ತಿ; ಶಾಕ್ತ ಸಂಪ್ರದಾಯ ಈ ಸೂಕ್ತವನ್ನು ದೇವಿಯ ವೇದೋಕ್ತ ಘೋಷಣೆ ಎಂದು ಓದುತ್ತದೆ.'] },
  { at: 'rv 1.3.10',
    m: ['May Sarasvatī, the purifier, rich in rewards, wealthy in thought, desire our sacrifice.', 'ಪಾವನಳೂ ಸಮೃದ್ಧಿದಾಯಿನಿಯೂ ಚಿಂತನೆಯೇ ಸಂಪತ್ತಾದವಳೂ ಆದ ಸರಸ್ವತಿ ನಮ್ಮ ಯಜ್ಞವನ್ನು ಬಯಸಲಿ.'],
    w: [['पावका', '“purifying” — from √pū, to make clean.', '"ಪಾವನಗೊಳಿಸುವವಳು" — √ಪೂ (ಶುದ್ಧಗೊಳಿಸು).'],
      ['धियावसुः', '“whose wealth is thought” — a compound that keeps its first word’s ending (dhiyā).', '"ಚಿಂತನೆಯೇ ಸಂಪತ್ತಾದವಳು" — ಮೊದಲ ಪದದ ವಿಭಕ್ತಿ ಉಳಿಸಿಕೊಂಡ ಅಲುಕ್ ಸಮಾಸ (ಧಿಯಾ).'],
      ['वष्टु', '“may she desire” — imperative of √vaś, to wish.', '"ಬಯಸಲಿ" — √ವಶ್ (ಇಚ್ಛಿಸು) ಧಾತುವಿನ ಲೋಟ್.']],
    u: ['Recited in Sarasvatī worship and at the beginning of learning. Here Sarasvatī is already both the river and the power of inspired thought.', 'ಸರಸ್ವತೀಪೂಜೆ ಮತ್ತು ವಿದ್ಯಾರಂಭದಲ್ಲಿ ಪಠಣ. ಇಲ್ಲಿ ಸರಸ್ವತಿ ನದಿಯೂ ಪ್ರೇರಿತ ಚಿಂತನೆಯ ಶಕ್ತಿಯೂ ಆಗಿದ್ದಾಳೆ.'] },
  { at: 'rv 2.41.16',
    m: ['Best of mothers, best of rivers, best of goddesses, Sarasvatī: we are as if without honour; mother, give us renown.', 'ಮಾತೃಶ್ರೇಷ್ಠೆ, ನದೀಶ್ರೇಷ್ಠೆ, ದೇವೀಶ್ರೇಷ್ಠೆ ಸರಸ್ವತಿಯೇ, ನಾವು ಕೀರ್ತಿಯಿಲ್ಲದವರಂತಿದ್ದೇವೆ; ತಾಯಿ, ನಮಗೆ ಕೀರ್ತಿಯನ್ನು ನೀಡು.'],
    w: [['अम्बितमे', '“O best of mothers” — ambā with the superlative -tama, vocative.', '"ಓ ಶ್ರೇಷ್ಠ ತಾಯಿಯೇ" — ಅಂಬಾ + ತಮಪ್, ಸಂಬೋಧನೆ.'],
      ['स्मसि', '“we are” — Vedic form of smaḥ, 1st person plural of √as.', '"ಇದ್ದೇವೆ" — ಸ್ಮಃ ಎಂಬುದರ ವೈದಿಕ ರೂಪ, √ಅಸ್ ಉತ್ತಮಪುರುಷ ಬಹುವಚನ.'],
      ['कृधि', '“make” — Vedic imperative of √kṛ (classical kuru).', '"ಮಾಡು" — √ಕೃ ಧಾತುವಿನ ವೈದಿಕ ಲೋಟ್ (ಲೌಕಿಕದಲ್ಲಿ ಕುರು).']],
    u: ['A beloved prayer to Sarasvatī, used in her worship and by students. The three superlatives in a row are a model of Vedic praise.', 'ಸರಸ್ವತಿಯ ಪ್ರಿಯ ಪ್ರಾರ್ಥನೆ; ಅವಳ ಪೂಜೆಯಲ್ಲಿ, ವಿದ್ಯಾರ್ಥಿಗಳಿಂದ ಪಠಣ. ಸಾಲಾಗಿ ಮೂರು ಅತಿಶಯ ರೂಪಗಳು ವೈದಿಕ ಸ್ತುತಿಯ ಮಾದರಿ.'] },
  { at: 'rv 1.1.9',
    m: ['Agni, be easy of approach to us, as a father to his son; stay with us for our well-being.', 'ಅಗ್ನಿಯೇ, ತಂದೆ ಮಗನಿಗೆ ಹೇಗೋ ಹಾಗೆ ನಮಗೆ ಸುಲಭವಾಗಿ ಸಮೀಪಿಸಬಲ್ಲವನಾಗು; ನಮ್ಮ ಕ್ಷೇಮಕ್ಕಾಗಿ ನಮ್ಮೊಂದಿಗಿರು.'],
    w: [['पितेव', 'pitā iva, “like a father” — the closeness asked of a god.', 'ಪಿತಾ ಇವ, "ತಂದೆಯಂತೆ" — ದೇವನಿಂದ ಕೇಳುವ ಆತ್ಮೀಯತೆ.'],
      ['सूपायनः', '“easy to approach” — su + upāyana.', '"ಸುಲಭವಾಗಿ ಸಮೀಪಿಸಬಹುದಾದವನು" — ಸು + ಉಪಾಯನ.'],
      ['स्वस्तये', '“for well-being” — dative of svasti (su + asti, it is well).', '"ಕ್ಷೇಮಕ್ಕಾಗಿ" — ಸ್ವಸ್ತಿ (ಸು + ಅಸ್ತಿ) ಪದದ ಚತುರ್ಥಿ.']],
    u: ['The last ṛk of the first hymn of the Ṛgveda. After the grand praise of the opening it ends on intimacy: the god as father.', 'ಋಗ್ವೇದದ ಮೊದಲ ಸೂಕ್ತದ ಕೊನೆಯ ಋಕ್. ಆರಂಭದ ಭವ್ಯ ಸ್ತುತಿಯ ನಂತರ ಆತ್ಮೀಯತೆಯಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ: ದೇವನು ತಂದೆಯಂತೆ.'] },
  { at: 'rv 4.58.3',
    m: ['Four are its horns, three its feet, two its heads, seven its hands. Bound threefold, the bull roars: the great god has entered mortals.', 'ಅದಕ್ಕೆ ನಾಲ್ಕು ಕೊಂಬುಗಳು, ಮೂರು ಪಾದಗಳು, ಎರಡು ತಲೆಗಳು, ಏಳು ಕೈಗಳು. ಮೂರು ಬಗೆಯಲ್ಲಿ ಬಂಧಿತವಾದ ವೃಷಭ ಗರ್ಜಿಸುತ್ತದೆ: ಮಹಾದೇವನು ಮರ್ತ್ಯರನ್ನು ಪ್ರವೇಶಿಸಿದ್ದಾನೆ.'],
    w: [['शृङ्गा', '“horns” — Vedic neuter plural in -ā (classical śṛṅgāṇi).', '"ಕೊಂಬುಗಳು" — ವೈದಿಕ ನಪುಂಸಕ ಬಹುವಚನ -ಆ (ಲೌಕಿಕದಲ್ಲಿ ಶೃಂಗಾಣಿ).'],
      ['रोरवीति', '“roars and roars” — intensive of √ru.', '"ಮತ್ತೆ ಮತ್ತೆ ಗರ್ಜಿಸುತ್ತದೆ" — √ರು ಧಾತುವಿನ ಯಙ್ಲುಗಂತ.'],
      ['त्रिधा बद्धः', '“bound threefold” — in chest, throat and head, says Patañjali.', '"ಮೂರು ಬಗೆಯಲ್ಲಿ ಬಂಧಿತ" — ಎದೆ, ಕಂಠ, ಶಿರಗಳಲ್ಲಿ ಎನ್ನುತ್ತಾನೆ ಪತಂಜಲಿ.']],
    u: ['Patañjali opens his Mahābhāṣya on grammar with it: the bull is language — four horns the four word-classes, three feet the three times, two heads the eternal and the produced word, seven hands the seven cases.', 'ಪತಂಜಲಿ ತನ್ನ ವ್ಯಾಕರಣ ಮಹಾಭಾಷ್ಯವನ್ನು ಇದರಿಂದ ಆರಂಭಿಸುತ್ತಾನೆ: ವೃಷಭ ಎಂದರೆ ಭಾಷೆ — ನಾಲ್ಕು ಕೊಂಬುಗಳು ನಾಲ್ಕು ಪದವರ್ಗಗಳು, ಮೂರು ಪಾದಗಳು ಮೂರು ಕಾಲಗಳು, ಎರಡು ತಲೆಗಳು ನಿತ್ಯ-ಕಾರ್ಯ ಶಬ್ದಗಳು, ಏಳು ಕೈಗಳು ಏಳು ವಿಭಕ್ತಿಗಳು.'] },
  { at: 'rv 1.164.39',
    m: ['The ṛks dwell in the imperishable, in the highest heaven, where all the gods have taken their seats. One who does not know that — what will he do with the ṛk? Those who know it sit here together.', 'ಋಕ್ಕುಗಳು ಅಕ್ಷರದಲ್ಲಿ, ಪರಮವ್ಯೋಮದಲ್ಲಿ ನೆಲೆಸಿವೆ; ಅಲ್ಲಿ ಎಲ್ಲ ದೇವತೆಗಳು ಕುಳಿತಿದ್ದಾರೆ. ಅದನ್ನು ಅರಿಯದವನು ಋಕ್ಕಿನಿಂದ ಏನು ಮಾಡಿಯಾನು? ಅರಿತವರು ಇಲ್ಲಿ ಒಟ್ಟಾಗಿ ಕುಳಿತಿದ್ದಾರೆ.'],
    w: [['अक्षरे', '“in the imperishable” — akṣara is also “syllable”: the word that does not perish.', '"ಅಕ್ಷರದಲ್ಲಿ" — ಅಕ್ಷರ ಎಂದರೆ ನಾಶವಿಲ್ಲದ್ದು, ಅಕ್ಷರ (ವರ್ಣ) ಕೂಡ.'],
      ['निषेदुः', '“they sat down” — ni + √sad, perfect, 3rd person plural.', '"ಕುಳಿತರು" — ನಿ + √ಸದ್, ಲಿಟ್, ಪ್ರಥಮಪುರುಷ ಬಹುವಚನ.'],
      ['करिष्यति', '“will do” — future of √kṛ.', '"ಮಾಡುವನು" — √ಕೃ ಧಾತುವಿನ ಲೃಟ್ (ಭವಿಷ್ಯತ್).']],
    u: ['Quoted in the Śvetāśvatara Upaniṣad (4.8): recitation without knowing what the words point to is incomplete. A reminder that the Veda asks to be understood, not only repeated.', 'ಶ್ವೇತಾಶ್ವತರ ಉಪನಿಷತ್ತಿನಲ್ಲಿ (೪.೮) ಉಲ್ಲೇಖ: ಪದಗಳು ಏನನ್ನು ಸೂಚಿಸುತ್ತವೆ ಎಂದು ಅರಿಯದ ಪಠಣ ಅಪೂರ್ಣ. ವೇದ ಕೇವಲ ಪುನರಾವರ್ತನೆಯಲ್ಲ, ಅರಿವನ್ನೂ ಕೇಳುತ್ತದೆ ಎಂಬ ಜ್ಞಾಪನೆ.'] },
  { at: 'rv 10.117.6',
    m: ['The thoughtless man gains food in vain; truly I say, it is his death. He feeds neither friend nor companion: one who eats alone, sins alone.', 'ವಿವೇಕವಿಲ್ಲದವನು ಆಹಾರವನ್ನು ವ್ಯರ್ಥವಾಗಿ ಪಡೆಯುತ್ತಾನೆ; ಸತ್ಯವನ್ನೇ ಹೇಳುತ್ತೇನೆ, ಅದು ಅವನ ಮರಣ. ಅವನು ಮಿತ್ರನನ್ನೂ ಸಹಚರನನ್ನೂ ಪೋಷಿಸುವುದಿಲ್ಲ: ಒಬ್ಬನೇ ತಿನ್ನುವವನು ಕೇವಲ ಪಾಪವನ್ನೇ ಉಣ್ಣುತ್ತಾನೆ.'],
    w: [['मोघम्', '“in vain, fruitless”.', '"ವ್ಯರ್ಥವಾಗಿ, ನಿಷ್ಫಲವಾಗಿ".'],
      ['केवलादी', '“one who eats alone” — kevala + ādin (eater).', '"ಒಬ್ಬನೇ ತಿನ್ನುವವನು" — ಕೇವಲ + ಆದಿನ್ (ತಿನ್ನುವವನು).'],
      ['केवलाघः', '“wholly sin” — kevala + agha; the pun mirrors kevalādī.', '"ಕೇವಲ ಪಾಪ" — ಕೇವಲ + ಅಘ; ಕೇವಲಾದೀ ಪದಕ್ಕೆ ಪ್ರತಿಧ್ವನಿ.']],
    u: ['From the hymn in praise of giving (10.117). The Bhagavad Gītā echoes it (3.13): those who cook only for themselves eat sin. A cornerstone of the duty of sharing food.', 'ದಾನಸ್ತುತಿಯ ಸೂಕ್ತದಿಂದ (೧೦.೧೧೭). ಭಗವದ್ಗೀತೆ (೩.೧೩) ಪ್ರತಿಧ್ವನಿಸುತ್ತದೆ: ತಮಗಾಗಿ ಮಾತ್ರ ಅಡುಗೆ ಮಾಡುವವರು ಪಾಪವನ್ನೇ ತಿನ್ನುತ್ತಾರೆ. ಅನ್ನವನ್ನು ಹಂಚಿಕೊಳ್ಳುವ ಧರ್ಮದ ಮೂಲಾಧಾರ.'] },
  { at: 'rv 10.34.13',
    m: ['Do not play with dice: plough your field. Delight in your wealth, thinking it much. There are your cattle, gambler, there your wife — so Savitṛ the noble has told me.', 'ದಾಳಗಳಿಂದ ಆಡಬೇಡ; ನಿನ್ನ ಹೊಲವನ್ನು ಉಳು. ನಿನ್ನ ಸಂಪತ್ತನ್ನು ಸಾಕಷ್ಟೆಂದು ತಿಳಿದು ಅದರಲ್ಲಿ ಸಂತೋಷಪಡು. ಜೂಜುಗಾರನೇ, ಅಲ್ಲಿವೆ ನಿನ್ನ ಹಸುಗಳು, ಅಲ್ಲಿ ನಿನ್ನ ಹೆಂಡತಿ — ಶ್ರೇಷ್ಠ ಸವಿತೃ ನನಗೆ ಹೀಗೆ ಹೇಳಿದನು.'],
    w: [['मा दीव्यः', '“do not gamble” — mā with the unaugmented aorist (injunctive) makes a prohibition.', '"ಜೂಜಾಡಬೇಡ" — ಮಾ + ಅಡಾಗಮವಿಲ್ಲದ ಲುಙ್ (ನಿಷೇಧ).'],
      ['कृषिमित्', 'kṛṣim it, “ploughing indeed” — it stresses the word before it.', 'ಕೃಷಿಮ್ ಇತ್, "ಕೃಷಿಯನ್ನೇ" — ಇತ್ ಹಿಂದಿನ ಪದಕ್ಕೆ ಒತ್ತು.'],
      ['बहु मन्यमानः', '“thinking it much” — present middle participle of √man.', '"ಹೆಚ್ಚೆಂದು ಭಾವಿಸುತ್ತ" — √ಮನ್ ಧಾತುವಿನ ಆತ್ಮನೇಪದ ವರ್ತಮಾನ ಕೃದಂತ.']],
    u: ['The moral of the Gambler’s Lament (10.34), a vivid confession of addiction. Honest work and contentment with what one has are given here as a word of the gods.', 'ಜೂಜುಗಾರನ ಪ್ರಲಾಪ (೧೦.೩೪) ಸೂಕ್ತದ ನೀತಿ — ವ್ಯಸನದ ಜೀವಂತ ತಪ್ಪೊಪ್ಪಿಗೆ. ಪ್ರಾಮಾಣಿಕ ಶ್ರಮ, ಇರುವುದರಲ್ಲಿ ತೃಪ್ತಿ — ದೇವವಾಣಿಯಾಗಿ ಇಲ್ಲಿ ಉಪದೇಶ.'] },
  { at: 'rv 10.71.4',
    m: ['One who looks does not see speech; one who listens does not hear her. But to another she reveals her body, as a loving, well-dressed wife to her husband.', 'ನೋಡುವ ಒಬ್ಬನು ವಾಕ್ಕನ್ನು ಕಾಣುವುದಿಲ್ಲ; ಕೇಳುವ ಒಬ್ಬನು ಅವಳನ್ನು ಕೇಳುವುದಿಲ್ಲ. ಆದರೆ ಇನ್ನೊಬ್ಬನಿಗೆ ಅವಳು ತನ್ನ ರೂಪವನ್ನು ತೋರುತ್ತಾಳೆ — ಪ್ರೀತಿಯ, ಸುಂದರ ವಸ್ತ್ರಧಾರಿಣಿ ಪತ್ನಿ ಪತಿಗೆ ತೋರುವಂತೆ.'],
    w: [['त्वः', '“one, a certain one” — a Vedic pronoun used in contrasts: one … another.', '"ಒಬ್ಬನು" — ವಿರೋಧದಲ್ಲಿ ಬಳಸುವ ವೈದಿಕ ಸರ್ವನಾಮ: ಒಬ್ಬನು … ಇನ್ನೊಬ್ಬನು.'],
      ['ददर्श', '“has seen” — perfect of √dṛś.', '"ಕಂಡಿದ್ದಾನೆ" — √ದೃಶ್ ಧಾತುವಿನ ಲಿಟ್.'],
      ['वि सस्रे', '“has revealed, opened” — perfect of vi + √sṛ.', '"ತೆರೆದಿಟ್ಟಿದ್ದಾಳೆ" — ವಿ + √ಸೃ, ಲಿಟ್.']],
    u: ['From the Jñāna Sūkta on the origin of language. Patañjali cites it: mere hearing is not understanding; meaning shows itself to those who study with love.', 'ಭಾಷೆಯ ಉಗಮದ ಮೇಲಿನ ಜ್ಞಾನಸೂಕ್ತದಿಂದ. ಪತಂಜಲಿ ಉಲ್ಲೇಖಿಸುತ್ತಾನೆ: ಕೇಳುವುದೇ ಅರಿವಲ್ಲ; ಪ್ರೀತಿಯಿಂದ ಅಧ್ಯಯನ ಮಾಡುವವನಿಗೆ ಅರ್ಥ ತಾನಾಗಿ ತೆರೆದುಕೊಳ್ಳುತ್ತದೆ.'] },
  { at: 'rv 1.113.16',
    m: ['Rise up! The breath of life has come to us; darkness has gone, light is coming. She has opened the path for the sun to travel; we have come where life is prolonged.', 'ಏಳಿರಿ! ಜೀವದ ಉಸಿರು ನಮ್ಮನ್ನು ತಲುಪಿದೆ; ಕತ್ತಲೆ ಹೋಯಿತು, ಬೆಳಕು ಬರುತ್ತಿದೆ. ಸೂರ್ಯನು ಸಾಗಲು ಅವಳು ದಾರಿ ತೆರೆದಿದ್ದಾಳೆ; ಆಯುಸ್ಸು ವೃದ್ಧಿಯಾಗುವಲ್ಲಿಗೆ ನಾವು ಬಂದಿದ್ದೇವೆ.'],
    w: [['उदीर्ध्वम्', '“rise up!” — ud + √īr, imperative 2nd plural, middle.', '"ಏಳಿರಿ!" — ಉತ್ + √ಈರ್, ಲೋಟ್ ಮಧ್ಯಮಪುರುಷ ಬಹುವಚನ, ಆತ್ಮನೇಪದ.'],
      ['असुः', '“life-breath, vital spirit”.', '"ಜೀವಶಕ್ತಿ, ಪ್ರಾಣ".'],
      ['आगात्', '“has come” — ā + √gā, root aorist.', '"ಬಂದಿದೆ" — ಆ + √ಗಾ, ಲುಙ್.']],
    u: ['From a great hymn to Uṣas, Dawn. Each morning is a return of life: the verse is a call to wake and greet the day.', 'ಉಷಸ್ಸಿನ ಮಹಾಸೂಕ್ತದಿಂದ. ಪ್ರತಿ ಮುಂಜಾನೆ ಜೀವದ ಮರಳುವಿಕೆ: ಎದ್ದು ದಿನವನ್ನು ಸ್ವಾಗತಿಸುವ ಕರೆ.'] },
  { at: 'rv 10.127.1',
    m: ['Night, the goddess, has come and looked out in many places with her eyes; she has put on all her glories.', 'ರಾತ್ರಿದೇವಿ ಬಂದು ತನ್ನ ಕಣ್ಣುಗಳಿಂದ ಅನೇಕ ಕಡೆ ನೋಡಿದ್ದಾಳೆ; ತನ್ನ ಎಲ್ಲ ಶೋಭೆಗಳನ್ನು ಧರಿಸಿದ್ದಾಳೆ.'],
    w: [['व्यख्यत्', '“has looked out” — vi + √khyā, aorist.', '"ನೋಡಿದ್ದಾಳೆ" — ವಿ + √ಖ್ಯಾ, ಲುಙ್.'],
      ['अक्षभिः', '“with eyes” — instrumental plural of akṣan; the stars are her eyes.', '"ಕಣ್ಣುಗಳಿಂದ" — ಅಕ್ಷನ್ ಪದದ ತೃತೀಯಾ ಬಹುವಚನ; ನಕ್ಷತ್ರಗಳೇ ಅವಳ ಕಣ್ಣುಗಳು.'],
      ['पुरुत्रा', '“in many places” — puru + the locative adverb suffix -trā.', '"ಅನೇಕ ಕಡೆ" — ಪುರು + ತ್ರಾ ಪ್ರತ್ಯಯ.']],
    u: ['The Rātri Sūkta, recited at nightfall for protection and, in the Śākta tradition, before the Devī Māhātmya.', 'ರಾತ್ರಿಸೂಕ್ತ: ರಕ್ಷಣೆಗಾಗಿ ರಾತ್ರಿ ಆರಂಭದಲ್ಲಿ ಪಠಣ; ಶಾಕ್ತ ಸಂಪ್ರದಾಯದಲ್ಲಿ ದೇವೀಮಾಹಾತ್ಮ್ಯದ ಮೊದಲು.'] },
  { at: 'rv 7.89.5',
    m: ['Whatever wrong we humans do against the divine folk, Varuṇa, if through thoughtlessness we have broken your laws — do not harm us for that sin, O god.', 'ವರುಣನೇ, ಮನುಷ್ಯರಾದ ನಾವು ದೈವೀ ಜನರ ವಿರುದ್ಧ ಏನೇ ದ್ರೋಹ ಮಾಡಿದರೂ, ಅವಿವೇಕದಿಂದ ನಿನ್ನ ಧರ್ಮಗಳನ್ನು ಮುರಿದರೂ — ದೇವನೇ, ಆ ಪಾಪಕ್ಕಾಗಿ ನಮ್ಮನ್ನು ಹಿಂಸಿಸಬೇಡ.'],
    w: [['अचित्ती', '“through thoughtlessness” — Vedic instrumental of acitti.', '"ಅವಿವೇಕದಿಂದ" — ಅಚಿತ್ತಿ ಪದದ ವೈದಿಕ ತೃತೀಯಾ.'],
      ['युयोपिम', '“we have violated” — perfect of √yup.', '"ಮುರಿದಿದ್ದೇವೆ" — √ಯುಪ್ ಧಾತುವಿನ ಲಿಟ್.'],
      ['मा … रीरिषः', '“do not harm” — mā with the reduplicated aorist of √riṣ.', '"ಹಿಂಸಿಸಬೇಡ" — ಮಾ + √ರಿಷ್ ಧಾತುವಿನ ದ್ವಿರುಕ್ತ ಲುಙ್.']],
    u: ['From Vasiṣṭha’s prayers to Varuṇa for forgiveness, among the most personal in the Veda. Used in prāyaścitta, rites of atonement, and in personal prayer.', 'ಕ್ಷಮೆಗಾಗಿ ವರುಣನಿಗೆ ವಸಿಷ್ಠರ ಪ್ರಾರ್ಥನೆಗಳಿಂದ — ವೇದದ ಅತ್ಯಂತ ವೈಯಕ್ತಿಕ ಪ್ರಾರ್ಥನೆಗಳಲ್ಲೊಂದು. ಪ್ರಾಯಶ್ಚಿತ್ತ ವಿಧಿಗಳಲ್ಲಿ, ವೈಯಕ್ತಿಕ ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ ಬಳಕೆ.'] },
  { at: 'rv 5.82.5',
    m: ['God Savitṛ, drive away all evils; bring to us whatever is good.', 'ಸವಿತೃದೇವನೇ, ಎಲ್ಲ ದುರಿತಗಳನ್ನು ದೂರ ಓಡಿಸು; ಯಾವುದು ಶುಭವೋ ಅದನ್ನು ನಮಗೆ ತಾ.'],
    w: [['दुरितानि', '“evils, troubles” — dur + ita, what has gone badly.', '"ದುರಿತಗಳು, ಕಷ್ಟಗಳು" — ದುರ್ + ಇತ, ಕೆಟ್ಟದಾಗಿ ಹೋದದ್ದು.'],
      ['परा सुव … आ सुव', '“impel away … impel here” — one verb, √sū (Savitṛ’s own), with opposite prefixes.', '"ದೂರ ಪ್ರೇರಿಸು … ಇತ್ತ ಪ್ರೇರಿಸು" — ಸವಿತೃವಿನದೇ ಧಾತು √ಸೂ, ವಿರುದ್ಧ ಉಪಸರ್ಗಗಳೊಂದಿಗೆ.'],
      ['भद्रम्', '“good, auspicious”.', '"ಶುಭ, ಮಂಗಳ".']],
    u: ['Short and complete, this is one of the most widely recited prayers, used daily and at the start of many rites. Its play on parā and ā shows how prefixes turn one verb into opposites.', 'ಸಂಕ್ಷಿಪ್ತವೂ ಪೂರ್ಣವೂ ಆದ, ಅತ್ಯಂತ ವ್ಯಾಪಕವಾಗಿ ಪಠಿಸುವ ಪ್ರಾರ್ಥನೆ; ನಿತ್ಯ ಮತ್ತು ಅನೇಕ ವಿಧಿಗಳ ಆರಂಭದಲ್ಲಿ. ಪರಾ ಮತ್ತು ಆ ಉಪಸರ್ಗಗಳ ಆಟ ಒಂದೇ ಧಾತುವನ್ನು ವಿರುದ್ಧಾರ್ಥಗಳಾಗಿಸುತ್ತದೆ.'] },
  { at: 'rv 1.97.1',
    m: ['May our sin be burnt away; Agni, shine wealth upon us. May our sin be burnt away.', 'ನಮ್ಮ ಪಾಪ ಸುಟ್ಟುಹೋಗಲಿ; ಅಗ್ನಿಯೇ, ಸಂಪತ್ತನ್ನು ನಮ್ಮ ಮೇಲೆ ಬೆಳಗಿಸು. ನಮ್ಮ ಪಾಪ ಸುಟ್ಟುಹೋಗಲಿ.'],
    w: [['शोशुचत्', '“may it burn away, flare away” — intensive of √śuc, to blaze.', '"ಸುಟ್ಟುಹೋಗಲಿ" — √ಶುಚ್ (ಉರಿ) ಧಾತುವಿನ ಯಙ್ಲುಗಂತ.'],
      ['अघम्', '“sin, harm, distress”.', '"ಪಾಪ, ಕೇಡು, ಸಂಕಟ".'],
      ['शुशुग्धि', '“shine forth” — perfect imperative of √śuc.', '"ಬೆಳಗು" — √ಶುಚ್ ಧಾತುವಿನ ಲಿಟ್ ಲೋಟ್ ರೂಪ.']],
    u: ['The refrain “apa naḥ śośucad agham” closes every ṛk of this short hymn, recited for purification. The sound itself, with its repeated śu, imitates the crackle of fire.', '"ಅಪ ನಃ ಶೋಶುಚದಘಮ್" ಪಲ್ಲವಿ ಈ ಚಿಕ್ಕ ಸೂಕ್ತದ ಪ್ರತಿ ಋಕ್ಕನ್ನು ಮುಗಿಸುತ್ತದೆ; ಶುದ್ಧಿಗಾಗಿ ಪಠಣ. ಪುನರಾವರ್ತಿತ "ಶು" ಧ್ವನಿಯೇ ಬೆಂಕಿಯ ಚಟಪಟವನ್ನು ಅನುಕರಿಸುತ್ತದೆ.'] },
  { at: 'rv 9.113.7',
    m: ['Where light is unceasing, the world where the sun is placed — set me there, Pavamāna, in the undying, imperishable world. O drop, flow for Indra.', 'ಅಖಂಡ ಜ್ಯೋತಿ ಇರುವಲ್ಲಿ, ಸೂರ್ಯನು ನೆಲೆಸಿರುವ ಲೋಕದಲ್ಲಿ — ಪವಮಾನನೇ, ನನ್ನನ್ನು ಆ ಅಮೃತ, ಅಕ್ಷಯ ಲೋಕದಲ್ಲಿ ಇರಿಸು. ಇಂದುವೇ, ಇಂದ್ರನಿಗಾಗಿ ಹರಿ.'],
    w: [['अजस्रम्', '“unceasing” — a + jasra, never failing.', '"ಅಖಂಡ" — ಅ + ಜಸ್ರ, ಎಂದೂ ಕುಗ್ಗದ.'],
      ['धेहि', '“place, set” — imperative of √dhā.', '"ಇರಿಸು" — √ಧಾ ಧಾತುವಿನ ಲೋಟ್.'],
      ['अक्षिते', '“in the imperishable” — a + kṣita, locative.', '"ಅಕ್ಷಯದಲ್ಲಿ" — ಅ + ಕ್ಷಿತ, ಸಪ್ತಮೀ.']],
    u: ['From the closing verses of the Soma maṇḍala, with the refrain “indrāyendo pari srava”. Among the Veda’s clearest longings for a world of light and freedom beyond death.', 'ಸೋಮಮಂಡಲದ ಅಂತಿಮ ಋಕ್ಕುಗಳಿಂದ, "ಇಂದ್ರಾಯೇಂದೋ ಪರಿ ಸ್ರವ" ಪಲ್ಲವಿಯೊಂದಿಗೆ. ಮರಣದಾಚೆಯ ಬೆಳಕು-ಸ್ವಾತಂತ್ರ್ಯದ ಲೋಕಕ್ಕಾಗಿ ವೇದದ ಅತ್ಯಂತ ಸ್ಪಷ್ಟ ಹಂಬಲಗಳಲ್ಲೊಂದು.'] },
  { at: 'rv 8.48.3',
    m: ['We have drunk the soma, we have become immortal, we have gone to the light, we have found the gods. What can hostility do to us now, what the malice of a mortal, O immortal one?', 'ಸೋಮವನ್ನು ಕುಡಿದಿದ್ದೇವೆ, ಅಮೃತರಾಗಿದ್ದೇವೆ, ಜ್ಯೋತಿಯನ್ನು ಸೇರಿದ್ದೇವೆ, ದೇವತೆಗಳನ್ನು ಕಂಡಿದ್ದೇವೆ. ಓ ಅಮೃತನೇ, ಈಗ ಶತ್ರುತ್ವ ನಮಗೆ ಏನು ಮಾಡೀತು, ಮರ್ತ್ಯನ ದ್ವೇಷ ಏನು ಮಾಡೀತು?'],
    w: [['अपाम', '“we have drunk” — aorist of √pā.', '"ಕುಡಿದಿದ್ದೇವೆ" — √ಪಾ ಧಾತುವಿನ ಲುಙ್.'],
      ['अभूम', '“we have become” — aorist of √bhū.', '"ಆಗಿದ್ದೇವೆ" — √ಭೂ ಲುಙ್.'],
      ['अगन्म … अविदाम', '“we have gone … we have found” — aorists of √gam and √vid: four in a row, each a step of ecstasy.', '"ಹೋಗಿದ್ದೇವೆ … ಕಂಡಿದ್ದೇವೆ" — √ಗಮ್, √ವಿದ್ ಲುಙ್: ಸಾಲಾಗಿ ನಾಲ್ಕು, ಆನಂದದ ಒಂದೊಂದು ಹೆಜ್ಜೆ.']],
    u: ['The rapture of soma in four aorists — completed actions — giving the sense that the goal is already reached. One of the most quoted descriptions of Vedic spiritual experience.', 'ನಾಲ್ಕು ಲುಙ್ ರೂಪಗಳಲ್ಲಿ (ಪೂರ್ಣ ಕ್ರಿಯೆಗಳು) ಸೋಮದ ಆನಂದ — ಗುರಿ ಈಗಾಗಲೇ ತಲುಪಿದ ಭಾವ. ವೈದಿಕ ಆಧ್ಯಾತ್ಮಿಕ ಅನುಭವದ ಅತ್ಯಂತ ಉಲ್ಲೇಖಿತ ವರ್ಣನೆಗಳಲ್ಲೊಂದು.'] },
  { at: 'rv 2.12.1',
    m: ['He who, as soon as born, was first and wise, the god who surpassed the gods with his power, before whose might the two worlds trembled by the greatness of his strength — he, O people, is Indra.', 'ಹುಟ್ಟಿದೊಡನೆ ಮೊದಲಿಗನೂ ಮನಸ್ವಿಯೂ ಆದವನು, ತನ್ನ ಶಕ್ತಿಯಿಂದ ದೇವತೆಗಳನ್ನು ಮೀರಿದ ದೇವನು, ಯಾರ ಬಲದ ಮಹಿಮೆಗೆ ದ್ಯಾವಾಪೃಥಿವಿಗಳು ನಡುಗಿದವೋ — ಜನರೇ, ಅವನೇ ಇಂದ್ರ.'],
    w: [['जनासः', '“O people” — Vedic nominative plural in -āsaḥ (classical janāḥ).', '"ಜನರೇ" — ವೈದಿಕ ಪ್ರಥಮಾ ಬಹುವಚನ -ಆಸಃ (ಲೌಕಿಕದಲ್ಲಿ ಜನಾಃ).'],
      ['मनस्वान्', '“wise, full of mind” — manas + the possessive suffix -vat.', '"ಮನಸ್ವಿ, ಬುದ್ಧಿವಂತ" — ಮನಸ್ + ಮತುಪ್ (ವತ್).'],
      ['पर्यभूषत्', '“surpassed, encompassed” — pari + √bhūṣ, imperfect.', '"ಮೀರಿದನು, ಆವರಿಸಿದನು" — ಪರಿ + √ಭೂಷ್, ಲಙ್.']],
    u: ['Gṛtsamada’s great hymn with the refrain “sa janāsa indraḥ”, answering doubters who asked whether Indra exists. A model of how a refrain builds a hymn.', '"ಸ ಜನಾಸ ಇಂದ್ರಃ" ಪಲ್ಲವಿಯುಳ್ಳ ಗೃತ್ಸಮದರ ಮಹಾಸೂಕ್ತ — ಇಂದ್ರನಿದ್ದಾನೆಯೇ ಎಂದು ಸಂಶಯಿಸಿದವರಿಗೆ ಉತ್ತರ. ಪಲ್ಲವಿ ಸೂಕ್ತವನ್ನು ಹೇಗೆ ಕಟ್ಟುತ್ತದೆ ಎಂಬುದರ ಮಾದರಿ.'] },
  { at: 'rv 10.151.1',
    m: ['By faith the fire is kindled; by faith the offering is made. With our words we proclaim faith, at the head of good fortune.', 'ಶ್ರದ್ಧೆಯಿಂದ ಅಗ್ನಿ ಪ್ರಜ್ವಲಿಸುತ್ತದೆ; ಶ್ರದ್ಧೆಯಿಂದ ಹವಿಸ್ಸು ಅರ್ಪಿತವಾಗುತ್ತದೆ. ಸೌಭಾಗ್ಯದ ಶಿಖರದಲ್ಲಿರುವ ಶ್ರದ್ಧೆಯನ್ನು ನಮ್ಮ ಮಾತುಗಳಿಂದ ಸಾರುತ್ತೇವೆ.'],
    w: [['श्रद्धया', '“by faith” — instrumental of śraddhā (śrad + √dhā, to set the heart on).', '"ಶ್ರದ್ಧೆಯಿಂದ" — ಶ್ರದ್ಧಾ (ಶ್ರತ್ + √ಧಾ, ಹೃದಯವನ್ನು ಇಡು) ಪದದ ತೃತೀಯಾ.'],
      ['समिध्यते', '“is kindled” — passive of sam + √idh.', '"ಪ್ರಜ್ವಲಿಸಲ್ಪಡುತ್ತದೆ" — ಸಮ್ + √ಇಧ್, ಕರ್ಮಣಿ.'],
      ['हूयते', '“is offered” — passive of √hu.', '"ಅರ್ಪಿಸಲ್ಪಡುತ್ತದೆ" — √ಹು ಧಾತುವಿನ ಕರ್ಮಣಿ ರೂಪ.']],
    u: ['From the Śraddhā Sūkta, ascribed to the woman seer Śraddhā Kāmāyanī. Ritual works only through earnest trust — a theme the Gītā develops (17.3: a person is made of their faith).', 'ಋಷಿಕೆ ಶ್ರದ್ಧಾ ಕಾಮಾಯನೀಗೆ ಆರೋಪಿತವಾದ ಶ್ರದ್ಧಾಸೂಕ್ತದಿಂದ. ವಿಧಿ ಶ್ರದ್ಧೆಯಿಂದ ಮಾತ್ರ ಫಲಿಸುತ್ತದೆ — ಗೀತೆ (೧೭.೩) ಮುಂದುವರಿಸುವ ವಿಷಯ: ಮನುಷ್ಯ ಶ್ರದ್ಧಾಮಯ.'] },
  { at: 'rv 4.40.5',
    m: ['The swan dwelling in the bright, the good one dwelling in the air, the priest dwelling at the altar, the guest dwelling in the house; dwelling in men, in the best, in order, in the sky; born of the waters, of cows, of order, of the mountain — he is Order itself.', 'ಪ್ರಕಾಶದಲ್ಲಿರುವ ಹಂಸ, ಅಂತರಿಕ್ಷದಲ್ಲಿರುವ ವಸು, ವೇದಿಯಲ್ಲಿರುವ ಹೋತೃ, ಮನೆಯಲ್ಲಿರುವ ಅತಿಥಿ; ಮನುಷ್ಯರಲ್ಲಿ, ಶ್ರೇಷ್ಠರಲ್ಲಿ, ಋತದಲ್ಲಿ, ಆಕಾಶದಲ್ಲಿ ಇರುವವನು; ಜಲ, ಗೋವು, ಋತ, ಪರ್ವತಗಳಿಂದ ಜನಿಸಿದವನು — ಅವನೇ ಋತ.'],
    w: [['शुचिषत्', '“sitting in the bright” — śuci + sad; every pāda builds compounds in -sad, “sitting in”.', '"ಪ್ರಕಾಶದಲ್ಲಿ ಕುಳಿತವನು" — ಶುಚಿ + ಸದ್; ಪ್ರತಿ ಪಾದದಲ್ಲೂ -ಸದ್ ಸಮಾಸಗಳು.'],
      ['अब्जाः', '“born of the waters” — ap + jā; then a run of compounds in -jā, “born of”.', '"ಜಲದಿಂದ ಜನಿಸಿದವನು" — ಅಪ್ + ಜಾ; ನಂತರ -ಜಾ ಸಮಾಸಗಳ ಸಾಲು.'],
      ['हंसः', '“swan” — the sun, and later the soul, gliding through the sky.', '"ಹಂಸ" — ಆಕಾಶದಲ್ಲಿ ಸಾಗುವ ಸೂರ್ಯ; ಮುಂದೆ ಜೀವಾತ್ಮ.']],
    u: ['Recited in sun worship; the Kaṭha Upaniṣad (2.2.2) quotes it for the Self that dwells everywhere. A tour de force of compounds: one being present in every place and born of every source.', 'ಸೂರ್ಯಾರಾಧನೆಯಲ್ಲಿ ಪಠಣ; ಕಠೋಪನಿಷತ್ತು (೨.೨.೨) ಎಲ್ಲೆಡೆ ನೆಲೆಸಿದ ಆತ್ಮಕ್ಕಾಗಿ ಉಲ್ಲೇಖಿಸುತ್ತದೆ. ಸಮಾಸಗಳ ಅದ್ಭುತ ರಚನೆ: ಒಂದೇ ಸತ್ತ್ವ ಪ್ರತಿ ಸ್ಥಳದಲ್ಲೂ ಇದ್ದು ಪ್ರತಿ ಮೂಲದಿಂದ ಜನಿಸಿದ್ದು.'] },
  { at: 'rv 1.154.2',
    m: ['Viṣṇu is praised for this heroic deed, like a fearsome beast roaming the mountains, in whose three wide strides all the worlds dwell.', 'ಪರ್ವತಗಳಲ್ಲಿ ಸಂಚರಿಸುವ ಭಯಂಕರ ಮೃಗದಂತೆ ವಿಷ್ಣುವು ತನ್ನ ಪರಾಕ್ರಮಕ್ಕಾಗಿ ಸ್ತುತಿಸಲ್ಪಡುತ್ತಾನೆ; ಅವನ ಮೂರು ವಿಶಾಲ ಹೆಜ್ಜೆಗಳಲ್ಲಿ ಎಲ್ಲ ಲೋಕಗಳು ನೆಲೆಸಿವೆ.'],
    w: [['मृगो न', '“like a wild beast” — in the Veda na after a noun often means “like”, not “not”.', '"ಕಾಡುಮೃಗದಂತೆ" — ವೇದದಲ್ಲಿ ನಾಮಪದದ ನಂತರದ "ನ" ಹಲವು ಬಾರಿ "ಹಾಗೆ" ಎಂದರ್ಥ, "ಇಲ್ಲ" ಅಲ್ಲ.'],
      ['विक्रमणेषु', '“in the strides” — vi + √kram; the root of Trivikrama.', '"ಹೆಜ್ಜೆಗಳಲ್ಲಿ" — ವಿ + √ಕ್ರಮ್; ತ್ರಿವಿಕ್ರಮ ಪದದ ಮೂಲ.'],
      ['अधिक्षियन्ति', '“dwell in” — adhi + √kṣi.', '"ನೆಲೆಸಿವೆ" — ಅಧಿ + √ಕ್ಷಿ.']],
    u: ['From the Viṣṇu Sūkta (1.154), source of the Trivikrama and Vāmana stories. Recited in Viṣṇu worship; the three strides measure earth, sky and the highest heaven.', 'ವಿಷ್ಣುಸೂಕ್ತದಿಂದ (೧.೧೫೪) — ತ್ರಿವಿಕ್ರಮ, ವಾಮನ ಕಥೆಗಳ ಮೂಲ. ವಿಷ್ಣುಪೂಜೆಯಲ್ಲಿ ಪಠಣ; ಮೂರು ಹೆಜ್ಜೆಗಳು ಭೂಮಿ, ಅಂತರಿಕ್ಷ, ಪರಮವ್ಯೋಮಗಳನ್ನು ಅಳೆಯುತ್ತವೆ.'] },
  { at: 'rv 7.35.1',
    m: ['May Indra and Agni be gracious to us with their help; gracious Indra and Varuṇa, to whom offerings are made; gracious Indra and Soma, for welfare and health; gracious Indra and Pūṣan in the winning of strength.', 'ಇಂದ್ರಾಗ್ನಿಗಳು ತಮ್ಮ ರಕ್ಷಣೆಗಳಿಂದ ನಮಗೆ ಶುಭಕರರಾಗಲಿ; ಹವಿಸ್ಸು ಸ್ವೀಕರಿಸುವ ಇಂದ್ರಾವರುಣರು ಶುಭಕರರಾಗಲಿ; ಇಂದ್ರಾಸೋಮರು ಕ್ಷೇಮ-ಆರೋಗ್ಯಕ್ಕಾಗಿ ಶುಭಕರರಾಗಲಿ; ಇಂದ್ರಾಪೂಷರು ಬಲಸಂಪಾದನೆಯಲ್ಲಿ ಶುಭಕರರಾಗಲಿ.'],
    w: [['भवताम्', '“may the two be” — dual imperative of √bhū.', '"ಇಬ್ಬರೂ ಆಗಲಿ" — √ಭೂ ಧಾತುವಿನ ದ್ವಿವಚನ ಲೋಟ್.'],
      ['अवोभिः', '“with help, with protection” — instrumental plural of avas.', '"ರಕ್ಷಣೆಗಳಿಂದ" — ಅವಸ್ ಪದದ ತೃತೀಯಾ ಬಹುವಚನ.'],
      ['शं योः', '“welfare and health” — an old pair of blessing words.', '"ಕ್ಷೇಮ ಮತ್ತು ಆರೋಗ್ಯ" — ಆಶೀರ್ವಾದದ ಪ್ರಾಚೀನ ಪದಜೋಡಿ.']],
    u: ['Opening of Vasiṣṭha’s Śānti Sūkta (7.35), where nearly every pāda begins with “śaṃ naḥ”. Recited in śānti rites and in the Vedic pārāyaṇa for peace.', 'ವಸಿಷ್ಠರ ಶಾಂತಿಸೂಕ್ತದ (೭.೩೫) ಆರಂಭ — ಬಹುತೇಕ ಪ್ರತಿ ಪಾದ "ಶಂ ನಃ"ಯಿಂದ. ಶಾಂತಿವಿಧಿಗಳಲ್ಲಿ, ಶಾಂತಿಗಾಗಿ ವೇದಪಾರಾಯಣದಲ್ಲಿ ಪಠಣ.'] },
  { at: 'rv 10.97.1',
    m: ['The plants that were born of old, three ages before the gods — of these brown ones I now ponder the hundred and seven forms.', 'ದೇವತೆಗಳಿಗಿಂತ ಮೂರು ಯುಗ ಮೊದಲು ಹುಟ್ಟಿದ ಪ್ರಾಚೀನ ಓಷಧಿಗಳು — ಕಂದು ಬಣ್ಣದ ಅವುಗಳ ನೂರೇಳು ರೂಪಗಳನ್ನು ಈಗ ಚಿಂತಿಸುತ್ತೇನೆ.'],
    w: [['ओषधीः', '“plants, herbs” — especially healing ones.', '"ಸಸ್ಯಗಳು, ಓಷಧಿಗಳು" — ಮುಖ್ಯವಾಗಿ ಔಷಧೀಯವಾದವು.'],
      ['त्रियुगम्', '“three ages” — tri + yuga.', '"ಮೂರು ಯುಗಗಳು" — ತ್ರಿ + ಯುಗ.'],
      ['मनै', '“I ponder” — a rare Vedic subjunctive of √man.', '"ಚಿಂತಿಸುತ್ತೇನೆ" — √ಮನ್ ಧಾತುವಿನ ಅಪರೂಪದ ವೈದಿಕ ಲೇಟ್.']],
    u: ['The Oṣadhī Sūkta, sung by a healer to the plants; Āyurveda looks to it as an early root. Plants are called mothers and older than the gods.', 'ಓಷಧೀಸೂಕ್ತ — ವೈದ್ಯನು ಸಸ್ಯಗಳಿಗೆ ಹಾಡುವುದು; ಆಯುರ್ವೇದ ಇದನ್ನು ತನ್ನ ಪ್ರಾಚೀನ ಬೇರು ಎಂದು ನೋಡುತ್ತದೆ. ಸಸ್ಯಗಳನ್ನು ತಾಯಂದಿರೆಂದೂ ದೇವತೆಗಳಿಗಿಂತ ಹಳೆಯವೆಂದೂ ಕರೆಯುತ್ತದೆ.'] },
  { at: 'rv 10.186.1',
    m: ['May the Wind blow medicine to us, healing and joy to our hearts; may he lengthen our lives.', 'ವಾತನು ನಮಗೆ ಔಷಧವನ್ನು ಬೀಸಲಿ — ನಮ್ಮ ಹೃದಯಕ್ಕೆ ಶಾಂತಿ ಮತ್ತು ಸುಖವನ್ನು; ಅವನು ನಮ್ಮ ಆಯುಸ್ಸನ್ನು ವೃದ್ಧಿಸಲಿ.'],
    w: [['वात आ वातु', '“may the Wind blow” — the god’s name Vāta and the verb vātu share the root √vā.', '"ವಾತನು ಬೀಸಲಿ" — ದೇವತೆಯ ಹೆಸರು ವಾತ ಮತ್ತು ಕ್ರಿಯಾಪದ ವಾತು ಒಂದೇ ಧಾತು √ವಾ.'],
      ['भेषजम्', '“medicine, remedy”.', '"ಔಷಧ, ಪರಿಹಾರ".'],
      ['तारिषत्', '“may he extend” — aorist subjunctive of pra + √tṝ.', '"ವೃದ್ಧಿಸಲಿ" — ಪ್ರ + √ತೄ ಧಾತುವಿನ ಲುಙ್ ಲೇಟ್.']],
    u: ['A short healing prayer to the wind. Breath and fresh air as medicine: the hymn is recited for health and long life.', 'ಗಾಳಿಗೆ ಚಿಕ್ಕ ಆರೋಗ್ಯ ಪ್ರಾರ್ಥನೆ. ಉಸಿರು ಮತ್ತು ಶುದ್ಧ ಗಾಳಿಯೇ ಔಷಧ: ಆರೋಗ್ಯ ಮತ್ತು ದೀರ್ಘಾಯುಸ್ಸಿಗಾಗಿ ಪಠಣ.'] },
  { at: 'rv 1.18.6',
    m: ['I have approached the lord of the assembly, the wonderful, dear friend of Indra, the desirable — for gain and for wisdom.', 'ಸಭೆಯ ಒಡೆಯನೂ ಅದ್ಭುತನೂ ಇಂದ್ರನ ಪ್ರಿಯನೂ ಕಾಮ್ಯನೂ ಆದವನನ್ನು ಲಾಭಕ್ಕಾಗಿ ಮತ್ತು ಮೇಧಾಶಕ್ತಿಗಾಗಿ ಸಮೀಪಿಸಿದ್ದೇನೆ.'],
    w: [['सदसस्पतिम्', '“lord of the assembly” — the genitive sadasaḥ is kept inside the compound.', '"ಸಭೆಯ ಒಡೆಯ" — ಷಷ್ಠಿ ಸದಸಃ ಸಮಾಸದಲ್ಲೂ ಉಳಿದಿದೆ (ಅಲುಕ್).'],
      ['मेधाम्', '“wisdom, intelligence, retentive power”.', '"ಮೇಧೆ, ಬುದ್ಧಿ, ಧಾರಣಶಕ್ತಿ".'],
      ['अयासिषम्', '“I have approached, sought” — s-aorist of √yā.', '"ಸಮೀಪಿಸಿದ್ದೇನೆ, ಯಾಚಿಸಿದ್ದೇನೆ" — √ಯಾ ಧಾತುವಿನ ಸ್-ಲುಙ್.']],
    u: ['Recited by students for medhā, the power to learn and retain, and at the start of study and assemblies.', 'ಮೇಧಾಶಕ್ತಿಗಾಗಿ (ಕಲಿಯುವ ಮತ್ತು ಧರಿಸುವ ಶಕ್ತಿ) ವಿದ್ಯಾರ್ಥಿಗಳು ಪಠಿಸುವ ಮಂತ್ರ; ಅಧ್ಯಯನ ಮತ್ತು ಸಭೆಗಳ ಆರಂಭದಲ್ಲೂ.'] },
  { at: 'rv 10.85.36',
    m: ['I take your hand for good fortune, that you may reach old age with me, your husband. Bhaga, Aryaman, Savitṛ and Purandhi have given you to me, for the household.', 'ಸೌಭಾಗ್ಯಕ್ಕಾಗಿ ನಿನ್ನ ಕೈ ಹಿಡಿಯುತ್ತೇನೆ — ಪತಿಯಾದ ನನ್ನೊಂದಿಗೆ ನೀನು ವೃದ್ಧಾಪ್ಯವನ್ನು ತಲುಪುವಂತೆ. ಭಗ, ಅರ್ಯಮ, ಸವಿತೃ, ಪುರಂಧಿ ಗೃಹಸ್ಥಧರ್ಮಕ್ಕಾಗಿ ನಿನ್ನನ್ನು ನನಗೆ ಕೊಟ್ಟಿದ್ದಾರೆ.'],
    w: [['गृभ्णामि', '“I grasp, take” — Vedic present of √grabh (classical gṛhṇāmi).', '"ಹಿಡಿಯುತ್ತೇನೆ" — √ಗ್ರಭ್ ಧಾತುವಿನ ವೈದಿಕ ಲಟ್ (ಲೌಕಿಕದಲ್ಲಿ ಗೃಹ್ಣಾಮಿ).'],
      ['सौभगत्वाय', '“for good fortune” — dative of saubhagatva.', '"ಸೌಭಾಗ್ಯಕ್ಕಾಗಿ" — ಸೌಭಗತ್ವ ಪದದ ಚತುರ್ಥಿ.'],
      ['जरदष्टिः', '“reaching old age” — jarat + aṣṭi.', '"ವೃದ್ಧಾಪ್ಯವನ್ನು ತಲುಪುವವಳು" — ಜರತ್ + ಅಷ್ಟಿ.']],
    u: ['The pāṇigrahaṇa mantra: the groom says it as he takes the bride’s hand, the heart of the Vedic wedding. It comes from the hymn of Sūryā’s marriage.', 'ಪಾಣಿಗ್ರಹಣ ಮಂತ್ರ: ವರನು ವಧುವಿನ ಕೈ ಹಿಡಿಯುವಾಗ ಹೇಳುವುದು — ವೈದಿಕ ವಿವಾಹದ ಹೃದಯ. ಸೂರ್ಯಾವಿವಾಹ ಸೂಕ್ತದಿಂದ.'] },
  { at: 'rv 10.85.42',
    m: ['Stay here, you two; do not be parted. Reach your full span of life, playing with sons and grandsons, rejoicing in your own home.', 'ನೀವಿಬ್ಬರೂ ಇಲ್ಲೇ ಇರಿ; ಬೇರಾಗಬೇಡಿ. ಪುತ್ರ-ಪೌತ್ರರೊಂದಿಗೆ ಆಡುತ್ತ, ನಿಮ್ಮ ಮನೆಯಲ್ಲಿ ಸಂತೋಷಪಡುತ್ತ ಪೂರ್ಣ ಆಯುಸ್ಸನ್ನು ಪಡೆಯಿರಿ.'],
    w: [['स्तम्', '“be (you two)” — dual imperative of √as.', '"ಇರಿ (ನೀವಿಬ್ಬರು)" — √ಅಸ್ ಧಾತುವಿನ ದ್ವಿವಚನ ಲೋಟ್.'],
      ['मा वि यौष्टम्', '“do not be separated” — mā with the s-aorist of vi + √yu.', '"ಬೇರಾಗಬೇಡಿ" — ಮಾ + ವಿ + √ಯು ಧಾತುವಿನ ಸ್-ಲುಙ್.'],
      ['व्यश्नुतम्', '“attain (you two)” — vi + √aś, dual imperative.', '"ಪಡೆಯಿರಿ (ಇಬ್ಬರೂ)" — ವಿ + √ಅಶ್, ದ್ವಿವಚನ ಲೋಟ್.']],
    u: ['A blessing on the newly wed couple, said in the wedding rite. The grammar itself is the blessing: every verb is in the dual — they are addressed as one pair.', 'ನವದಂಪತಿಗಳಿಗೆ ವಿವಾಹವಿಧಿಯಲ್ಲಿ ಆಶೀರ್ವಾದ. ವ್ಯಾಕರಣವೇ ಆಶೀರ್ವಾದ: ಪ್ರತಿ ಕ್ರಿಯಾಪದ ದ್ವಿವಚನದಲ್ಲಿ — ಇಬ್ಬರನ್ನೂ ಒಂದು ಜೋಡಿಯಾಗಿ ಸಂಬೋಧನೆ.'] },
  { at: 'rv 1.89.6',
    m: ['May Indra of great fame grant us well-being; may Pūṣan who knows all grant us well-being; may Tārkṣya of unhurt wheel grant us well-being; may Bṛhaspati grant us well-being.', 'ಮಹಾಕೀರ್ತಿಯ ಇಂದ್ರನು ನಮಗೆ ಸ್ವಸ್ತಿಯನ್ನು ನೀಡಲಿ; ಸರ್ವಜ್ಞ ಪೂಷನು ಸ್ವಸ್ತಿ ನೀಡಲಿ; ಅರಿಷ್ಟನೇಮಿ ತಾರ್ಕ್ಷ್ಯನು ಸ್ವಸ್ತಿ ನೀಡಲಿ; ಬೃಹಸ್ಪತಿ ನಮಗೆ ಸ್ವಸ್ತಿಯನ್ನು ನೀಡಲಿ.'],
    w: [['स्वस्ति', '“well-being” — su + asti, “it is well”; the root of svastika.', '"ಕ್ಷೇಮ" — ಸು + ಅಸ್ತಿ, "ಒಳ್ಳೆಯದಿದೆ"; ಸ್ವಸ್ತಿಕ ಪದದ ಮೂಲ.'],
      ['वृद्धश्रवाः', '“of grown fame” — vṛddha + śravas, a bahuvrīhi.', '"ಬೆಳೆದ ಕೀರ್ತಿಯುಳ್ಳವನು" — ವೃದ್ಧ + ಶ್ರವಸ್, ಬಹುವ್ರೀಹಿ.'],
      ['अरिष्टनेमिः', '“whose wheel-rim is unhurt” — Tārkṣya, the divine steed or Garuḍa.', '"ಹಾನಿಯಾಗದ ಚಕ್ರಧಾರೆಯುಳ್ಳವನು" — ತಾರ್ಕ್ಷ್ಯ, ದಿವ್ಯ ಅಶ್ವ ಅಥವಾ ಗರುಡ.']],
    u: ['Recited with “bhadraṃ karṇebhiḥ” as the śānti pāṭha of the Atharvaveda Upaniṣads and at the start of rites — four times svasti, for protection from every side.', '"ಭದ್ರಂ ಕರ್ಣೇಭಿಃ" ಜೊತೆಗೆ ಅಥರ್ವವೇದದ ಉಪನಿಷತ್ತುಗಳ ಶಾಂತಿಪಾಠವಾಗಿ ಮತ್ತು ವಿಧಿಗಳ ಆರಂಭದಲ್ಲಿ ಪಠಣ — ಎಲ್ಲ ದಿಕ್ಕುಗಳಿಂದ ರಕ್ಷಣೆಗಾಗಿ ನಾಲ್ಕು ಬಾರಿ ಸ್ವಸ್ತಿ.'] },
  { at: 'rv 5.51.15',
    m: ['May we follow the path of well-being, like the sun and the moon. May we meet again with one who gives, who does no harm, who knows.', 'ಸೂರ್ಯ-ಚಂದ್ರರಂತೆ ನಾವು ಕ್ಷೇಮದ ದಾರಿಯಲ್ಲಿ ನಡೆಯೋಣ. ದಾನಿಯೂ ಅಹಿಂಸಕನೂ ಜ್ಞಾನಿಯೂ ಆದವನೊಂದಿಗೆ ಮತ್ತೆ ಸೇರೋಣ.'],
    w: [['सूर्याचन्द्रमसौ', '“sun and moon” — a dual dvandva compound, each member in the dual form.', '"ಸೂರ್ಯ ಮತ್ತು ಚಂದ್ರ" — ದ್ವಿವಚನ ದ್ವಂದ್ವ ಸಮಾಸ; ಎರಡೂ ಪದಗಳು ದ್ವಿವಚನ ರೂಪದಲ್ಲಿ.'],
      ['चरेम', '“may we go” — optative of √car.', '"ನಡೆಯೋಣ" — √ಚರ್ ವಿಧಿಲಿಙ್.'],
      ['ददता अघ्नता जानता', '“with one who gives, does not harm, knows” — three participles in the instrumental.', '"ಕೊಡುವ, ಹಿಂಸಿಸದ, ಅರಿತ ವ್ಯಕ್ತಿಯೊಂದಿಗೆ" — ಮೂರು ಕೃದಂತಗಳು ತೃತೀಯೆಯಲ್ಲಿ.']],
    u: ['A traveller’s prayer, recited before journeys: like the sun and moon on their unfailing paths, and with good companions to meet on the way.', 'ಪ್ರಯಾಣಿಕನ ಪ್ರಾರ್ಥನೆ; ಪ್ರಯಾಣದ ಮೊದಲು ಪಠಣ: ತಪ್ಪದ ದಾರಿಯ ಸೂರ್ಯ-ಚಂದ್ರರಂತೆ, ದಾರಿಯಲ್ಲಿ ಒಳ್ಳೆಯ ಜೊತೆಗಾರರೊಂದಿಗೆ.'] },
  { at: 'rv 10.81.3',
    m: ['With eyes on every side, faces on every side, arms on every side, feet on every side, the one god, creating heaven and earth, forges them together with his arms and wings.', 'ಎಲ್ಲೆಡೆ ಕಣ್ಣುಗಳು, ಎಲ್ಲೆಡೆ ಮುಖಗಳು, ಎಲ್ಲೆಡೆ ತೋಳುಗಳು, ಎಲ್ಲೆಡೆ ಪಾದಗಳು ಉಳ್ಳ ಏಕದೇವನು ದ್ಯಾವಾಪೃಥಿವಿಗಳನ್ನು ಸೃಷ್ಟಿಸುತ್ತ ತನ್ನ ತೋಳು-ರೆಕ್ಕೆಗಳಿಂದ ಅವನ್ನು ಊದಿ ರೂಪಿಸುತ್ತಾನೆ.'],
    w: [['विश्वतश्चक्षुः', '“eyes on all sides” — viśvatas (from all sides) + cakṣus.', '"ಎಲ್ಲೆಡೆ ಕಣ್ಣುಳ್ಳವನು" — ವಿಶ್ವತಸ್ + ಚಕ್ಷುಸ್.'],
      ['धमति', '“blows, forges” — √dham, the smith’s bellows.', '"ಊದುತ್ತಾನೆ, ಕುಲುಮೆಯಲ್ಲಿ ರೂಪಿಸುತ್ತಾನೆ" — √ಧಮ್, ಕಮ್ಮಾರನ ತಿದಿ.'],
      ['द्यावाभूमी', '“heaven and earth” — a dual dvandva.', '"ಆಕಾಶ ಮತ್ತು ಭೂಮಿ" — ದ್ವಿವಚನ ದ್ವಂದ್ವ.']],
    u: ['From the Viśvakarma Sūkta; the Śvetāśvatara Upaniṣad (3.3) repeats it for the Lord. Recited in Viśvakarma pūjā, honouring craft and making as divine.', 'ವಿಶ್ವಕರ್ಮಸೂಕ್ತದಿಂದ; ಶ್ವೇತಾಶ್ವತರ ಉಪನಿಷತ್ತು (೩.೩) ಈಶ್ವರನಿಗಾಗಿ ಪುನರುಚ್ಚರಿಸುತ್ತದೆ. ವಿಶ್ವಕರ್ಮಪೂಜೆಯಲ್ಲಿ ಪಠಣ — ಶಿಲ್ಪ, ನಿರ್ಮಾಣಗಳನ್ನು ದೈವಿಕವೆಂದು ಗೌರವಿಸುವುದು.'] },
  { at: 'rv 6.47.18',
    m: ['He became the counterpart of every form; that form of his is for us to behold. Indra goes about in many forms by his powers of māyā; ten hundred horses are yoked for him.', 'ಅವನು ಪ್ರತಿಯೊಂದು ರೂಪಕ್ಕೂ ಪ್ರತಿರೂಪನಾದನು; ಅವನ ಆ ರೂಪ ನಾವು ನೋಡುವುದಕ್ಕಾಗಿ. ಇಂದ್ರನು ತನ್ನ ಮಾಯಾಶಕ್ತಿಗಳಿಂದ ಅನೇಕ ರೂಪಗಳಲ್ಲಿ ಸಂಚರಿಸುತ್ತಾನೆ; ಅವನಿಗೆ ಸಾವಿರ ಕುದುರೆಗಳು ಹೂಡಲ್ಪಟ್ಟಿವೆ.'],
    w: [['रूपंरूपम्', '“form after form, every form” — a repeated word (āmreḍita) for “each”.', '"ಪ್ರತಿ ರೂಪ" — ಆಮ್ರೇಡಿತ (ಪುನರುಕ್ತ ಪದ), "ಪ್ರತಿಯೊಂದು" ಎಂಬರ್ಥ.'],
      ['मायाभिः', '“by his powers of māyā” — wondrous creative power, later “illusion”.', '"ಮಾಯಾಶಕ್ತಿಗಳಿಂದ" — ಅದ್ಭುತ ಸೃಜನಶಕ್ತಿ; ಮುಂದೆ "ಭ್ರಮೆ" ಎಂಬರ್ಥ.'],
      ['ईयते', '“goes about” — passive-form present of √i.', '"ಸಂಚರಿಸುತ್ತಾನೆ" — √ಇ ಧಾತುವಿನ ಕರ್ಮಣಿರೂಪ ಲಟ್.']],
    u: ['The Bṛhadāraṇyaka Upaniṣad (2.5.19) quotes it for Brahman appearing as all forms. A key verse for the history of the word māyā.', 'ಬೃಹದಾರಣ್ಯಕ ಉಪನಿಷತ್ತು (೨.೫.೧೯) ಎಲ್ಲ ರೂಪಗಳಾಗಿ ತೋರುವ ಬ್ರಹ್ಮನಿಗಾಗಿ ಉಲ್ಲೇಖಿಸುತ್ತದೆ. "ಮಾಯಾ" ಪದದ ಇತಿಹಾಸದ ಮುಖ್ಯ ಮಂತ್ರ.'] },
  { at: 'rv 1.164.45',
    m: ['Speech is measured in four quarters; the wise who have insight know them. Three, hidden in secret, do not stir; the fourth is what humans speak.', 'ವಾಕ್ಕು ನಾಲ್ಕು ಪಾದಗಳಾಗಿ ಅಳೆಯಲ್ಪಟ್ಟಿದೆ; ಮನೀಷಿಗಳಾದ ಬ್ರಾಹ್ಮಣರು ಅವುಗಳನ್ನು ಬಲ್ಲರು. ಮೂರು ಗುಹೆಯಲ್ಲಿ ಅಡಗಿದ್ದು ಚಲಿಸುವುದಿಲ್ಲ; ನಾಲ್ಕನೆಯದನ್ನು ಮನುಷ್ಯರು ಮಾತನಾಡುತ್ತಾರೆ.'],
    w: [['परिमिता', '“measured” — pari + √mā, past participle.', '"ಅಳೆಯಲ್ಪಟ್ಟ" — ಪರಿ + √ಮಾ, ಕ್ತ ಕೃದಂತ.'],
      ['गुहा', '“in secret, in the cave” — an old instrumental used as an adverb.', '"ಗುಹೆಯಲ್ಲಿ, ರಹಸ್ಯದಲ್ಲಿ" — ಕ್ರಿಯಾವಿಶೇಷಣವಾಗಿ ಬಳಸುವ ಪ್ರಾಚೀನ ತೃತೀಯಾ.'],
      ['तुरीयम्', '“the fourth”.', '"ನಾಲ್ಕನೆಯದು".']],
    u: ['Later grammar and Tantra read the four quarters as parā, paśyantī, madhyamā and vaikharī — speech from its silent source to the spoken word. Only the last is heard.', 'ಮುಂದಿನ ವ್ಯಾಕರಣ ಮತ್ತು ತಂತ್ರ ನಾಲ್ಕು ಪಾದಗಳನ್ನು ಪರಾ, ಪಶ್ಯಂತೀ, ಮಧ್ಯಮಾ, ವೈಖರೀ ಎಂದು ಓದುತ್ತವೆ — ಮೌನ ಮೂಲದಿಂದ ಉಚ್ಚರಿತ ಶಬ್ದದವರೆಗೆ ವಾಕ್ಕು. ಕೊನೆಯದು ಮಾತ್ರ ಕೇಳಿಸುತ್ತದೆ.'] },
  { at: 'rv 10.53.6',
    m: ['Spinning the thread, follow the light of the world; guard the luminous paths made by insight. Weave without knots the work of the singers. Be human: bring forth the divine race.', 'ದಾರವನ್ನು ನೇಯುತ್ತ ಲೋಕದ ಬೆಳಕನ್ನು ಅನುಸರಿಸು; ಬುದ್ಧಿಯಿಂದ ನಿರ್ಮಿತವಾದ ಜ್ಯೋತಿರ್ಮಯ ದಾರಿಗಳನ್ನು ಕಾಪಾಡು. ಸ್ತೋತೃಗಳ ಕಾರ್ಯವನ್ನು ಗಂಟಿಲ್ಲದೆ ನೇಯಿ. ಮನುಷ್ಯನಾಗು; ದಿವ್ಯ ಜನಾಂಗವನ್ನು ಹುಟ್ಟುಹಾಕು.'],
    w: [['तन्तुम्', '“thread” — of the sacrifice, of tradition passed on.', '"ದಾರ" — ಯಜ್ಞದ, ಹಸ್ತಾಂತರಿತ ಪರಂಪರೆಯ ದಾರ.'],
      ['मनुर्भव', 'manuḥ bhava, “become Manu, be human”.', 'ಮನುಃ ಭವ, "ಮನುವಾಗು, ಮನುಷ್ಯನಾಗು".'],
      ['जनय', '“bring forth” — causative imperative of √jan.', '"ಹುಟ್ಟುಹಾಕು" — √ಜನ್ ಧಾತುವಿನ ಣಿಜಂತ ಲೋಟ್.']],
    u: ['“Manur bhava” has become a motto in modern times: be truly human, and so make the divine in people. The weaving image ties every generation to the thread of the sacrifice.', '"ಮನುರ್ಭವ" ಆಧುನಿಕ ಕಾಲದಲ್ಲಿ ಧ್ಯೇಯವಾಕ್ಯವಾಗಿದೆ: ನಿಜವಾದ ಮನುಷ್ಯನಾಗು, ಹಾಗೆ ಜನರಲ್ಲಿ ದಿವ್ಯತೆಯನ್ನು ಬೆಳೆಸು. ನೇಯ್ಗೆಯ ಉಪಮೆ ಪ್ರತಿ ತಲೆಮಾರನ್ನೂ ಯಜ್ಞದ ದಾರಕ್ಕೆ ಕಟ್ಟುತ್ತದೆ.'] },
  { at: 'rv 1.89.10',
    m: ['Aditi is the sky, Aditi the air, Aditi the mother, the father, the son. Aditi is all the gods and the five peoples; Aditi is what is born and what will be born.', 'ಅದಿತಿಯೇ ಆಕಾಶ, ಅದಿತಿಯೇ ಅಂತರಿಕ್ಷ, ಅದಿತಿಯೇ ತಾಯಿ, ತಂದೆ, ಮಗ. ಅದಿತಿಯೇ ಎಲ್ಲ ದೇವತೆಗಳು, ಐದು ಜನಾಂಗಗಳು; ಅದಿತಿಯೇ ಹುಟ್ಟಿದ್ದು ಮತ್ತು ಹುಟ್ಟಲಿರುವುದು.'],
    w: [['अदितिः', '“the boundless, the unbound” — a + diti (binding).', '"ಅಪರಿಮಿತ, ಬಂಧನವಿಲ್ಲದವಳು" — ಅ + ದಿತಿ (ಬಂಧನ).'],
      ['पञ्च जनाः', '“the five peoples” — all humankind.', '"ಐದು ಜನಾಂಗಗಳು" — ಸಮಸ್ತ ಮಾನವಕುಲ.'],
      ['जनित्वम्', '“what is to be born” — a gerundive-like noun of √jan.', '"ಹುಟ್ಟಲಿರುವುದು" — √ಜನ್ ಧಾತುವಿನ ಕೃತ್ಯಾರ್ಥಕ ನಾಮ.']],
    u: ['The closing ṛk of the Bhadra Sūkta (1.89). An early vision of one boundless reality as everything, recited at the end of the śānti prayers drawn from this hymn.', 'ಭದ್ರಸೂಕ್ತದ (೧.೮೯) ಕೊನೆಯ ಋಕ್. ಒಂದೇ ಅಪರಿಮಿತ ಸತ್ಯ ಎಲ್ಲವೂ ಆಗಿದೆ ಎಂಬ ಪ್ರಾಚೀನ ದರ್ಶನ; ಈ ಸೂಕ್ತದ ಶಾಂತಿಪ್ರಾರ್ಥನೆಗಳ ಕೊನೆಯಲ್ಲಿ ಪಠಣ.'] },
];
